        [HttpGet]
        [SessionExpireFilterAttributeClient]
        [ValidateInput(false)]
        public void ExportClientArea(short ClientRowID = 0)
        {
            try
            {

                //ClientRowID=Convert.ToInt16(Request.QueryString["ClientRowID"].ToString());
                int allClients = 0;

                int ClientUserRowID = 0;
                string ClientAccessType = Convert.ToString(Session["ClientAccessType"]);


                if (ClientAccessType == "3" && ClientRowID > 0)
                {
                    ClientUserRowID = ClientRowID;
                    ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
                    allClients = 0;
                    ViewBag.ClientRowID = ClientRowID;
                }

                if (ClientAccessType == "3" && ClientRowID == 0)
                {
                    ClientUserRowID = Convert.ToInt16(Session["ClientUserRowID"]);
                    ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
                    allClients = 1;
                }

                if (ClientAccessType == "2" && ClientRowID > 0)
                {
                    ClientUserRowID = Convert.ToInt32(Session["ClientUserRowID"]);
                    allClients = 0;
                    ViewBag.ClientRowID = ClientRowID;
                }

                if (ClientAccessType == "2" && ClientRowID == 0)
                {
                    ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
                    ClientUserRowID = Convert.ToInt32(Session["ClientUserRowID"]);
                    allClients = 1;
                }

                if (ClientAccessType == "1")
                {
                    ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
                    ClientUserRowID = Convert.ToInt32(Session["ClientUserRowID"]);
                    allClients = 1;
                }
                string caseStatus = "WIP";
                //short ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
                //int ClientUserRowID = Convert.ToInt32(Session["ClientUserRowID"]);
                string CreatedBy = Convert.ToString(Session["CreatedBy"]);
                string strFileName = "WIPCaseList_" + DateTime.Now.ToString("ddMMMyyyy");

                if (!string.IsNullOrEmpty(CreatedBy) && CreatedBy == "Client-User")
                {
                    var data = repoPQPersonal.GetClientAreaForExport1(ClientRowID, caseStatus, ClientUserRowID, allClients);
                    var value = data.Select(i => new { i.PersonalRowID, i.CandidateName, i.CandidateCode, i.ClientRefID, i.SecuritasID, i.CaseStatus, i.CreatedDate , i.casestatusname, i.EmployeeID });

                    ExportToExcel(value, strFileName);
                }
                else
                {

                    var data = repoPQPersonal.GetClientAreaForExport1(ClientRowID, caseStatus, ClientUserRowID, allClients);
                    if (ClientRowID == 974)
                    {
                        var value = data.Select(i => new { i.PersonalRowID, i.CandidateName, i.CandidateCode, i.ClientRefID, i.SecuritasID, i.CaseStatus, i.CreatedDate, i.PositionID, i.CostCenter, i.EmployeeID });
                        ExportToExcel(value, strFileName);
                    }
                    else if (ClientRowID == 1718)
                    {
                        var value = data.Select(i => new { i.PersonalRowID, i.CandidateName, i.CandidateCode, i.ClientRefID, i.SecuritasID, i.CaseStatus, i.CreatedDate, i.casestatusname, i.EmployeeID ,i.CheckType,i.InternalStatus , i.CheckID});
                        ExportToExcel(value, strFileName);
                    }
                    else if (ClientRowID == 1803)
                    {
                        ClientCustomize cc = new ClientCustomize();
                        DataSet ds = new DataSet();
                        ds = cc.getCasewiseSummaryDetail(ClientRowID, caseStatus, ClientUserRowID, "", allClients);

                        DataTable dt = ds.Tables[0];

                        string[] selectedColumns;

                        selectedColumns = new[]
                        {
                            "PersonalRowID",
                            "Candidate Name",
                            "CandidateCode",
                            "ClientRefID",
                            "Securitas ID",
                            "Case Status",
                            "Created On",
                            "casestatusName",
                            "RecruiterName",
                            "Employee Code",
                            "DateofJoining",
                            "Process Name",
                            "LineofBusiness",
                            "ORCID",
                            "TempID"
                        };

                        ExportToExcelEXL(dt, strFileName, selectedColumns);

                    }
                    else
                    {
                        var value = data.Select(i => new { i.PersonalRowID, i.CandidateName, i.CandidateCode, i.ClientRefID, i.SecuritasID, i.CaseStatus, i.CreatedDate , i.casestatusname,i.EmployeeID});
                        ExportToExcel(value, strFileName);
                    }
                }
            }
            catch (Exception Ex)
            {
                //ViewBag.ErrorMsg = Ex.Message;
                ViewBag.ErrorMsg = "Invalid paramerter value";
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }
        }


