        [HttpGet]
        [SessionExpireFilterAttributeClient]
        [ValidateInput(false)]
        public ActionResult ReInviteCandidate(string CompanyRefNo = "")
        {

            ClientCustomize cc = new ClientCustomize();

            checkViewModel model = new checkViewModel();
            try
            {
                int pageNo = 1;
                int pageSize = 100;

                DataTable dt = cc.GetAddcheckDetails(CompanyRefNo);

                List<CheckSummaryDetailViewModel> lmd = new List<CheckSummaryDetailViewModel>();
                if (dt.Rows.Count > 0)
                {
                    foreach (DataRow dr in dt.Rows)
                    {
                        lmd.Add(new CheckSummaryDetailViewModel
                        {
                            SecuritasID = (dr["CompanyRefNo"].ToString()),
                            CheckName = (dr["SubCheckName"].ToString()),
                            CheckStatus = dr["CheckStatus"].ToString(),
                            CheckStatusID = (dr["CheckStatusID"].ToString()),
                            OrderDate = (dr["orderDate"].ToString()),
                            OutDate = (dr["outDate"].ToString()),
                            CreatedDate = (dr["CreationDate"].ToString()),
                            ColorName = dr["ColorName"].ToString(),
                            ClientCheckRowID = Convert.ToInt32(dr["CandCheckRowID"]),
                            Name = (dr["Name"].ToString()),
                            PersonalRowID = Convert.ToInt32(dr["PersonalRowID"].ToString()),
                        });

                    }
                    model.TotalRecords = dt.Rows.Count;
                 
                }
                else
                {
                    model.TotalRecords = 0;
                }
                model.PageSize = 100;
                model.ClientServiceChecks = lmd.Skip((pageNo - 1) * pageSize).Take(pageSize);


            }
            catch (Exception Ex)
            {
                //ViewBag.ErrorMsg = Ex.Message;
                ViewBag.ErrorMsg = "Invalid paramerter value";
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }

            return View(model);
        }

        [HttpGet]
        [SessionExpireFilterAttributeClient]
        public JsonResult ClientCaseApproveByIDNew(int id = 0) /*, string DOJ = "", string clientrowid = ""*/
        {
            //if(clientrowid == "992" || clientrowid == "993" || clientrowid == "994" || clientrowid == "1125" || clientrowid == "1243")
            //{
            //    ClientCustomize ccc = new ClientCustomize();
            //    ccc.AddUpdateDoj(id, DOJ);
            //}
            TempPQCandidateCheck tpc = new TempPQCandidateCheck();
            bool result = false;
            //bool importResult = false;
            int count = 0;
            try
            {
                if (id > 0)
                {
                    int createdBy = 0;
                    createdBy = int.Parse(Convert.ToString(Session["ClientUserRowID"]));
                    string strResult = tpc.ApproveOrFinalSubmitByCandidateNewN(id, createdBy);
                    string ClientRowID = Session["ClientRowID"].ToString();
                    if (strResult == "Success")
                    {
                        #region Case/Check Action History Save 
                        clsCommonMethods.AddCaseActionHistoryByClient(Convert.ToInt32(id), "Re Invited case approved by HR temppqpersonalid " + id.ToString(), "Re Invited case approved by HR clientuserrowid " + createdBy.ToString());
                        #endregion

                        result = true;
                       
                    }
                    else
                    {
                        ViewBag.ErrorMsg = strResult;
                    }


                }
                else
                {
                    ViewBag.ErrorMsg = "Invalid Id!";
                }
            }
            catch (Exception Ex)
            {
                //ViewBag.ErrorMsg = Ex.Message;
                ViewBag.ErrorMsg = "Invalid paramerter value";
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }

            return Json(new { result, count }, JsonRequestBehavior.AllowGet);
        }

