        [SessionExpireFilterAttributeClient]
        public async Task<ActionResult> GetReport(string ImageName, string ReportType)
        {
            try
            {
                ReportType = clsCommonMethods.PDecrypt(ReportType);
                string imgname = (clsCommonMethods.PDecrypt(ImageName));
                string reportFileName = imgname + ".pdf";
                ClientCustomize cc = new ClientCustomize();

                int ClientUserID = Convert.ToInt32(Session["ClientUserRowID"]);
                int clientid = Convert.ToInt32(Session["ClientRowID"]);
                DataTable ddt = new DataTable();
                if (ReportType == "ReportReceivedInterim" && clientid == 890)
                {
                    ddt = cc.GetNorternReportInterimName(imgname, ClientUserID, ReportType);
                }
                else
                {
                    ddt = cc.getAutoExistCompRefNoReport(imgname, ClientUserID, ReportType);
                }
                string FldPathDoc = System.Configuration.ConfigurationManager.AppSettings["CandidateReportdoc"].ToString();
                string FldPathDoc_old = System.Configuration.ConfigurationManager.AppSettings["CandidateReportdoc_Old"].ToString();
                string CandidateOldReportPath = System.Configuration.ConfigurationManager.AppSettings["CandidateOldReportPath"].ToString();
                byte[] fileBytes = null;
                if (ddt.Rows.Count > 0)
                {
                    reportFileName = ddt.Rows[0]["ReportFileName"].ToString();
                    if (ReportType == "InterimReportCRC")
                    {
                        foreach (System.Data.DataRow row in ddt.Rows)
                        {
                            if (row["ReportType"] != null && row["ReportType"].ToString().Equals("CRC", StringComparison.OrdinalIgnoreCase))
                            {
                                if (row["ReportFileName"] != null)
                                {
                                    reportFileName = row["ReportFileName"].ToString();
                                    break;
                                }
                            }
                        }
                    }
                    else
                    {
                        reportFileName = ddt.Rows[0]["ReportFileName"].ToString();
                    }
                    if (FldPathDoc.StartsWith("~/"))
                    {
                        FldPathDoc = FldPathDoc.Replace("~/", @"D:/wwwroot2/");
                    }
                    if (FldPathDoc.StartsWith("/"))
                    {
                        FldPathDoc = @"D:/wwwroot2/" + FldPathDoc.Substring(1);
                    }
                    FldPathDoc = FldPathDoc + reportFileName;
                }
                else
                {

                    FldPathDoc = CandidateOldReportPath + GetOldReport(ImageName);


                    //FldPathDoc = FldPathDoc.Replace("wwwroot2", "wwwroot");
                }
                DataTable reportSecurity = new DataTable();
                reportSecurity = cc.ReportSeurityBYdatabase(Convert.ToInt16(Session["ClientRowID"]), imgname);
                if (reportSecurity.Rows.Count > 0)
                {


                    string contentType = "";
                    string directoryPath = Path.GetDirectoryName(FldPathDoc) + Path.DirectorySeparatorChar;
                    string fileName = Path.GetFileName(FldPathDoc);
                    HttpResponseMessage response = await _documentService.GetDocumentAsync(fileName, directoryPath);


                    if (response.IsSuccessStatusCode)
                    {
                        var jsonString = await response.Content.ReadAsStringAsync();
                        var obj = JsonConvert.DeserializeObject<DocumentResponse>(jsonString);

                        string docName = obj.DocumentName;
                        string base64Data = obj.DocumentValue;


                        var data = Convert.FromBase64String(base64Data);
                        contentType = System.Web.MimeMapping.GetMimeMapping(docName);
                        // var data = System.IO.File.ReadAllBytes(FldPathDoc);

                        using (MemoryStream input = new MemoryStream(data))
                        {
                            using (MemoryStream output = new MemoryStream())
                            {
                                string pwd = reportSecurity.Rows[0]["Reportvalidation"].ToString();
                                try
                                {
                                    PdfReader reader = new PdfReader(input);
                                    PdfEncryptor.Encrypt(reader, output, true, pwd, pwd, PdfWriter.ALLOW_SCREENREADERS);
                                    data = output.ToArray();
                                    Response.ContentType = "application/pdf";
                                    Response.AddHeader("content-disposition", "attachment;filename=" + repoDashboardClient.downloadReportFileName(imgname) + ".pdf");
                                    Response.Cache.SetCacheability(HttpCacheability.NoCache);
                                    Response.BinaryWrite(data);
                                    Response.End();
                                }

                                catch
                                {
                                    //if (System.IO.File.Exists(FldPathDoc))
                                    //{
                                    //    fileBytes = System.IO.File.ReadAllBytes(FldPathDoc);
                                    //}
                                    fileBytes = Convert.FromBase64String(base64Data);
                                    if (fileBytes != null)
                                    {
                                        return File(fileBytes, contentType, repoDashboardClient.downloadReportFileName(imgname) + ".pdf");
                                    }

                                }

                            }
                        }

                    }




                }
                else
                {
                    string contentType = "";
                    string directoryPath = Path.GetDirectoryName(FldPathDoc) + Path.DirectorySeparatorChar;
                    string fileName = Path.GetFileName(FldPathDoc);
                    HttpResponseMessage response = await _documentService.GetDocumentAsync(fileName, directoryPath);


                    if (response.IsSuccessStatusCode)
                    {
                        var jsonString = await response.Content.ReadAsStringAsync();
                        var obj = JsonConvert.DeserializeObject<DocumentResponse>(jsonString);

                        string docName = obj.DocumentName;
                        string base64Data = obj.DocumentValue;


                        fileBytes = Convert.FromBase64String(base64Data);
                        contentType = System.Web.MimeMapping.GetMimeMapping(docName);
                        if (fileBytes != null)
                        {
                            return File(fileBytes, contentType, repoDashboardClient.downloadReportFileName(imgname) + ".pdf");
                        }
                    }
                }
                return RedirectToAction("GetClientCasesDashBoardInfo", new { CaseStatus = "ReportReceived" });
            }
            catch (Exception Ex)
            {
             
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
                return RedirectToAction("GetClientCasesDashBoardInfo", new { CaseStatus = "ReportReceived" });
            }

        }

