        public static string GetOldReport(string CompanyRefNo)
        {
            var client = new RestClient("http://10.83.0.47:8087");
            var request = new RestRequest("http://10.83.0.47:8087/DownloadReport/", Method.GET);
            request.AddParameter("CompanyRefNo", CompanyRefNo);
            var response = client.ExecuteAsync(request);
            var test = response.Result;
            var result1 = response.Result.Content;
            Report_Root myDeserializedClass = JsonConvert.DeserializeObject<Report_Root>(result1);
            var filename = clsCommonMethods.PDecrypt(CompanyRefNo) + ".pdf";
            string filePath = System.Configuration.ConfigurationManager.AppSettings["CandidateOldReportPath"].ToString();
            System.IO.File.WriteAllBytes(filePath + filename, Convert.FromBase64String(myDeserializedClass.reportbase64));
            return filename;
        }
        public class Report_Root
        {
            public string reportbase64 { get; set; }
        }

