        [SessionExpireFilterAttributeClient]
        public async Task<ActionResult> GetReportInterim(string ImageName)
        {
            string imgname = (clsCommonMethods.PDecrypt(ImageName));
            string FldPathDoc = ConfigurationManager.AppSettings["CandidateReportdoc"].ToString();
            string FldPathDoc_old = System.Configuration.ConfigurationManager.AppSettings["CandidateReportdoc_Old"].ToString();
            byte[] fileBytes = null;
            string reportFileName = imgname + ".pdf";
            string contentType = string.Empty;
            ClientCustomize cc = new ClientCustomize();
            DataTable ddt = cc.getUploadedReportByReportType(imgname, "Interim");
            if (ddt.Rows.Count > 0)
            {
                reportFileName = ddt.Rows[0]["ReportFileName"].ToString();
                FldPathDoc = Server.MapPath(FldPathDoc) + reportFileName;
            }
            else
            {
                //FldPathDoc = Server.MapPath(FldPathDoc) + reportFileName;
                //FldPathDoc = FldPathDoc.Replace("wwwroot2", "wwwroot");
                FldPathDoc = FldPathDoc_old + reportFileName;
                //FldPathDoc = FldPathDoc.Replace("wwwroot2", "wwwroot");
            }

            //if (System.IO.File.Exists(FldPathDoc))
            //{
            //    fileBytes = System.IO.File.ReadAllBytes(FldPathDoc);
            //}
            if (FldPathDoc.StartsWith("~/"))
            {
                FldPathDoc = FldPathDoc.Replace("~/", @"D:/wwwroot2/");
            }
            if (FldPathDoc.StartsWith("/"))
            {
                FldPathDoc = @"D:/wwwroot2/" + FldPathDoc.Substring(1);
            }
            string directoryPath = Path.GetDirectoryName(FldPathDoc) + Path.DirectorySeparatorChar;
            string fileNames = Path.GetFileName(FldPathDoc);
            HttpResponseMessage response = await _documentService.GetDocumentAsync(fileNames, directoryPath);
            if (response.IsSuccessStatusCode)
            {
                var jsonString = await response.Content.ReadAsStringAsync();
                var obj = JsonConvert.DeserializeObject<DocumentResponse>(jsonString);

                string docName = obj.DocumentName;
                string base64Data = obj.DocumentValue;


                fileBytes = Convert.FromBase64String(base64Data);
                contentType = System.Web.MimeMapping.GetMimeMapping(docName);

                if (fileBytes != null)
                {
                    if (imgname.Contains("TGSPL"))
                    {
                        try
                        {
                            using (MemoryStream inputData = new MemoryStream(fileBytes))
                            {
                                using (MemoryStream outputData = new MemoryStream())
                                {
                                    string fileName = repoDashboardClient.downloadReportFileName(imgname) + ".pdf";
                                    string[] empcode = fileName.Split('-');
                                    string PDFFileword = "TEK" + empcode[0];//you can also generate Dynamic word                           
                                    PdfReader reader = new PdfReader(inputData);
                                    PdfEncryptor.Encrypt(reader, outputData, true, PDFFileword, PDFFileword, PdfWriter.ALLOW_SCREENREADERS);
                                    fileBytes = outputData.ToArray();
                                    return File(fileBytes, MediaTypeNames.Application.Octet, repoDashboardClient.downloadReportFileName(imgname) + ".pdf");
                                }
                            }
                        }
                        catch (Exception ee)
                        {
                            try
                            {
                                return File(fileBytes, MediaTypeNames.Application.Octet, repoDashboardClient.downloadReportFileName(imgname) + ".pdf");
                            }
                            catch
                            {
                                return RedirectToAction("GetClientCasesDashBoardInfo", new { CaseStatus = "ReportReceivedInterim" });
                            }
                        }
                    }
                    else
                        return File(fileBytes, MediaTypeNames.Application.Octet, repoDashboardClient.downloadReportFileName(imgname) + ".pdf");

                }
                else
                {
                    return RedirectToAction("GetClientCasesDashBoardInfo", new { CaseStatus = "ReportReceivedInterim" });
                }
            }
            else
            {
                return RedirectToAction("GetClientCasesDashBoardInfo", new { CaseStatus = "ReportReceivedInterim" });
            }

        }

