        [HttpGet]
        [SessionExpireFilterAttributeClient]
        [CachingHeadersFilterAttribute]
        [ValidateInput(false)]
        public ActionResult GetClientCasesDashBoardInfo(int page = 1, string sort = "", string sortDir = "desc", string Search = "", string CaseStatus = "", string RecievingToDate = "", string RecievingFromDate = "", string CompletedToDate = "", string CompletedFromDate = "", byte tatHours = 0, string ClientRowId = "", int ClientUserRowId = 0, string colorName = "", string SpocName = "")
        {
            DashboardClientCandidateListViewModel model = new DashboardClientCandidateListViewModel();
            try
            {

                int pageSize = 1000;
                int allClients = 0;
                short ClientRowID = 0;
                if (ClientRowId != "")
                {
                    //ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
                    ClientRowID = Convert.ToInt16(clsCommonMethods.PDecrypt(ClientRowId));
                }
                ClientCustomize cc = new ClientCustomize();
                int ClientUserRowID = 0;
                string ClientAccessType = Convert.ToString(Session["ClientAccessType"]);
                ViewBag.ErrorMsg = "";
                if (Search != "")
                {
                    if (clsCommonMethods.ValidateSQLInjuctionInput(Search) == false)
                    {
                        ViewBag.ErrorMsg = "Please Provide Valid Input";
                    }
                }
                if (ViewBag.ErrorMsg == "")
                {
                    if (ClientAccessType == "3" && ClientRowID > 0)
                    {
                        ClientUserRowID = ClientRowID;
                        ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
                        allClients = 0;

                    }

                    if (ClientAccessType == "3" && ClientRowID == 0)
                    {
                        ClientUserRowID = Convert.ToInt16(Session["ClientUserRowID"]);
                        ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
                        allClients = 1;
                    }

                    if (ClientAccessType == "2" && ClientRowID > 0)
                    {
                        ClientUserRowID = Convert.ToInt32(Session["ClientUserRowID"]);
                        allClients = 0;

                    }

                    if (ClientAccessType == "2" && ClientRowID == 0)
                    {
                        ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
                        ClientUserRowID = Convert.ToInt32(Session["ClientUserRowID"]);
                        allClients = 1;
                    }

                    if (ClientAccessType == "1")
                    {
                        ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
                        ClientUserRowID = Convert.ToInt32(Session["ClientUserRowID"]);
                        allClients = 1;
                    }

                    ViewBag.ClientRowID = Convert.ToString(ClientRowID);

                    if (!string.IsNullOrEmpty(CaseStatus) && (CaseStatus == "CaseApprpending" || CaseStatus == "Pendingcandidate"))
                    {
                        model = repoDashboardClient.GetClientTempDashBoardInfo1(page, pageSize, sort.ToLower(), sortDir.ToLower(), Search, CaseStatus, ClientRowID, RecievingToDate, RecievingFromDate, ClientUserRowID, allClients);
                    }  
                    else
                    {
                        model = repoDashboardClient.GetClientDashBoardInfo1(page, pageSize, sort.ToLower(), sortDir.ToLower(), Search, CaseStatus, ClientRowID, RecievingToDate, RecievingFromDate, CompletedToDate, CompletedFromDate, tatHours, ClientUserRowID, allClients);

                        if (!string.IsNullOrEmpty(colorName) &&
                            model != null &&
                            model.DashboardClientCandidates != null)
                        {
                            if (colorName != "Stop-No Color")
                            {
                                model.DashboardClientCandidates = model.DashboardClientCandidates
                                .Where(x => !string.IsNullOrEmpty(x.CaseStatus) &&
                                x.CaseStatus.Equals(colorName, StringComparison.OrdinalIgnoreCase))
                                .ToList();

                                model.TotalRecords = model.DashboardClientCandidates.Count();
                            }                            
                        }
                    }

                    DataTable DTReportVisibilty = cc.GetReportVisibility(ClientRowID, ClientUserRowID);
                    if (DTReportVisibilty.Rows.Count > 0)
                    {
                        if (!string.IsNullOrEmpty(DTReportVisibilty.Rows[0]["ReportVisible"].ToString()))
                        {
                            model.ReportVisibality = Convert.ToBoolean(DTReportVisibilty.Rows[0]["ReportVisible"]);

                        }
                        model.ReportVisibilityInterim = Convert.ToBoolean(DTReportVisibilty.Rows[0]["ReportVisibilityInterim"]);
                        model.ReportVisibilityFinal = Convert.ToBoolean(DTReportVisibilty.Rows[0]["ReportVisibilityFinal"]);
                    }

                    if (ClientRowID == 1803 && !string.IsNullOrEmpty(SpocName) && model != null && model.DashboardClientCandidates != null)
                    {
                        model.DashboardClientCandidates = model.DashboardClientCandidates
                            .Where(x => !string.IsNullOrEmpty(x.HRRecruiterName) &&
                                        x.HRRecruiterName.Equals(SpocName, StringComparison.OrdinalIgnoreCase))
                            .ToList();

                        model.TotalRecords = model.DashboardClientCandidates.Count();
                    }

                    if (model == null)
                    {
                        ViewBag.ErrorMsg = "No item found!";
                    }
                }
            }
            catch (Exception Ex)
            {
                //ViewBag.ErrorMsg = Ex.Message;
                ViewBag.ErrorMsg = "Invalid paramerter value";
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }


            ClientCustomize cn = new ClientCustomize();
            DataTable dt = cn.GetClientTMRights(Convert.ToInt16(Session["ClientUserRowID"]), Convert.ToInt16(Session["ClientRowID"]));
            if (dt.Rows.Count > 0)
            {
                ViewBag.InterimReportRights = dt.Rows[0]["InterimReportRights"] != DBNull.Value ? dt.Rows[0]["InterimReportRights"].ToString() != null ? Convert.ToBoolean(dt.Rows[0]["InterimReportRights"].ToString()) : false : false;
                ViewBag.FinalReportRights = dt.Rows[0]["FinalReportRights"] != DBNull.Value ? dt.Rows[0]["FinalReportRights"].ToString() != null ? Convert.ToBoolean(dt.Rows[0]["FinalReportRights"].ToString()) : false : false;
                ViewBag.WIPStatusRights = dt.Rows[0]["WIPStatusRights"] != DBNull.Value ? dt.Rows[0]["WIPStatusRights"].ToString() != null ? Convert.ToBoolean(dt.Rows[0]["WIPStatusRights"].ToString()) : false : false;
            }
            else
            {
                ViewBag.InterimReportRights = false;
                ViewBag.FinalReportRights = false;
                ViewBag.WIPStatusRights = false;
            }
            if (ViewBag.ClientRowID != null && ViewBag.ClientRowID.ToString() == "1803")
            {
                DataTable dtSpoc = cn.GetSpocListByClient(1803);
                ViewBag.SpocList = new SelectList(dtSpoc.DefaultView, "UserID", "UserID");
                ViewBag.SelectedSpoc = SpocName;
            }
            return View(model);

        }
        [HttpPost]
        [SessionExpireFilterAttributeClient]
        [CachingHeadersFilterAttribute]
        [ValidateInput(false)]
        public ActionResult GetClientCasesDashBoardInfo(FormCollection data)
        {
            //string[] idss = pids.personalrowid.Split(',');
            //string[] idss = pids.Split(',');
            string fname = data["pim"];
            string fileSavePath = @"C:\PDF\1516";
            string[] files = Directory.GetFiles(fileSavePath);
            List<FileInfo> f = new List<FileInfo>();

            foreach (string file in files)
            {
                FileInfo fi1 = new FileInfo(file);
                f.Add(fi1);
            }


            using (var memoryStream = new MemoryStream())
            {
                using (var ziparchive = new ZipArchive(memoryStream, ZipArchiveMode.Create, true))
                {
                    foreach (FileInfo fo in f)
                    {
                        ziparchive.CreateEntryFromFile(fo.FullName, fo.Name);
                    }
                    //return File(memoryStream.ToArray(), "application/zip");
                }

                return File(memoryStream.ToArray(), "application/zip", "Attachments.zip");
            }



        }

