        public void ExportToExcelEXL(DataTable dt, string strFileName, string[] selectedColumns)
        {
            try
            {
                DataTable exportTable;

                if (selectedColumns != null && selectedColumns.Length > 0)
                {
                    // Select only the requested columns
                    exportTable = dt.DefaultView.ToTable(
                        "Details",
                        false,
                        selectedColumns
                    );
                }
                else
                {
                    exportTable = dt.Copy();
                }

                using (ClosedXML.Excel.XLWorkbook wb = new ClosedXML.Excel.XLWorkbook())
                {
                    var ws = wb.Worksheets.Add(exportTable);

                    if (ws.Tables.Any())
                        ws.Tables.FirstOrDefault().ShowAutoFilter = false;

                    wb.Style.Font.Bold = true;

                    Response.Clear();
                    Response.Buffer = true;
                    Response.Charset = "";

                    Response.ContentType =
                        "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";

                    Response.AddHeader(
                        "content-disposition",
                        "attachment;filename=" + strFileName + ".xlsx"
                    );

                    using (MemoryStream MyMemoryStream = new MemoryStream())
                    {
                        wb.SaveAs(MyMemoryStream);
                        MyMemoryStream.WriteTo(Response.OutputStream);
                        Response.Flush();
                        Response.End();
                    }
                }
            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = "Invalid parameter value";

                clsCommonMethods.ErrorLog(
                    Server.MapPath("~\\ErrorLogs\\Logfiles"),
                    Ex.Message,
                    Ex.StackTrace
                );
            }
        }

