            PQClientUserListPagedModelNew model = new PQClientUserListPagedModelNew();
            try
            {
                if (Convert.ToString(Session["CreatedBy"]) == "Company-Client")
                {
                    short ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
                    int pageSize = 20;
                    model = GetClientUsersDetails(page, pageSize, Search, ClientRowID);
                    // model = repoLogin.GetClientUsers(page, pageSize, sort.ToLower(), sortDir.ToLower(), Search, ClientRowID);
