                                    ModelState.Clear();
                                    return RedirectToAction("ManageClientUsers");
                                }
                                else
                                {
                                    ViewBag.ErrorMsg = "There is some problem to save record. Please try again later!";
                                }
                            }
                            else if (checkCountStatus == -1)
                            {
                                TempData["SuccessMsg"] = "This client can not add the new user on this date due to client can not add more than 5 users of this client on same date";
                                ModelState.Clear();
                                return RedirectToAction("ManageClientUsers");
                            }
