        private string GetIP_Address()
        {
            string myIPAddr = "";
            foreach (NetworkInterface ni in NetworkInterface.GetAllNetworkInterfaces())
            {
                if (ni.OperationalStatus == OperationalStatus.Up)
                {
                    foreach (UnicastIPAddressInformation ip in ni.GetIPProperties().UnicastAddresses)
                    {
                        if (ip.Address.AddressFamily == AddressFamily.InterNetwork)
                        {
                            myIPAddr += $" Interface: {ni.Name}, IP Address: {ip.Address} ";
                        }
                    }
                }
            }
            return myIPAddr.ToString();
        }
        [HttpGet]
        public ActionResult UpdateDataBaseCheckReport(string sId, string pId)
        {
            CandidateDetaisforIDBCheckReport ModelOBj = new CandidateDetaisforIDBCheckReport();
            try
            {
                ClientCustomize CC = new ClientCustomize();
                int PersonalRowId = Convert.ToInt32(clsCommonMethods.PDecrypt(pId));
                int SubCheckRowId = Convert.ToInt32(clsCommonMethods.PDecrypt(sId));

                var Dt = CC.GetCandidatePersonalInfo_OR_IDBInfo(PersonalRowId, SubCheckRowId);
                if (Dt.Rows.Count > 0)
                {
                    ModelOBj.PersonalRowId = Convert.ToString(Dt.Rows[0]["PersonalRowId"]);
                    ModelOBj.SubCheckRowId = Convert.ToString(Dt.Rows[0]["SubCheckFamilyID"]);
                    ModelOBj.CandidateName = Convert.ToString(Dt.Rows[0]["Candidatename"]);
                    ModelOBj.CompanyRefNo = Convert.ToString(Dt.Rows[0]["CompanyRefNo"]);
                    ModelOBj.ClientRowId = Convert.ToString(Dt.Rows[0]["ClientRowID"]);
                    ModelOBj.DOB = Convert.ToString(Dt.Rows[0]["DOB"]);
                    ModelOBj.Country = Convert.ToString(Dt.Rows[0]["Country"]);
                    ModelOBj.Gender = Convert.ToString(Dt.Rows[0]["Gender"]);
                }
                ViewBag.ErrorMsg = "";
            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = Ex.Message;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }
            return View(ModelOBj);
        }
        [HttpPost]
        public ActionResult UpdateDataBaseCheckReport(CandidateDetaisforIDBCheckReport Model)
        {
            try
            {
                int Pid = Convert.ToInt32(Model.PersonalRowId);
                int Sid = Convert.ToInt32(Model.SubCheckRowId);
                int Cid = Convert.ToInt32(Model.ClientRowId);
                string CandidateName = Convert.ToString(Model.CandidateName);
                string CompanyRefNo = Convert.ToString(Model.CompanyRefNo);
                string DOB = Convert.ToString(Model.DOB);
                string Gender = Convert.ToString(Model.Gender);
                string Country = Convert.ToString(Model.Country);

                int rst = cc.UpdateWorldChecksCandidateName(Pid, Sid, CandidateName, Gender);

                string Result = ProcessWorldCheckReport(CompanyRefNo, Cid, Pid, Sid, DOB, Gender, Country, CandidateName);
                ViewBag.ErrorMsg = Result;

            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = Ex.Message;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }
            return View(Model);
        }


