        // Check Value for SQL keyword
        public string getval(string val)
        {
            string st = null;
            if (val != null)
            {

                st = "";
                var vals = val.ToUpper();
                vals = Regex.Replace(vals, @"\s", "");

                var Val = Get_List_SQLKeyword();

                if (val != null)
                {
                    var query = Val.Where(d => d.SQl_Check.Trim() == vals.Trim()).FirstOrDefault();
                    if (query != null)
                    {
                        if (query.Status == false)
                        {
                            st = "false";
                        }
                        else
                        {
                            st = "true";
                        }
                    }
                    if (st == "")
                    {
                        st = null;
                    }

                }
            }
            return st;
        }


        bool SendAlertMassageForCaseRegister(string CompanyRefNo1, string ClientSpocEmailID, string SpocEmailID, int clientRowid = 0, string AlertType = "", int PackageId = 0, int MailType = 0)
        {
            bool result = false;
            string MailSignature = string.Empty;
            string From = string.Empty;
            string DisplayName = string.Empty;
            string Cc = string.Empty; //Session["CSpocEmailID"].ToString();

            clsSendMail mail;
            mail = new clsSendMail();
            var signature = mail.GetCompanyMailSignature();

            if (signature != null)
            {
                MailSignature = string.Concat("For Securitas India. <br /><br />");
                MailSignature = string.Concat(MailSignature, "<b>", signature.CompanyName.Trim(), "</b><br /><b>Mobile: ", signature.MobileNo,
                    " | Direct Tel: ", signature.PhoneNo, " | Fax: ", signature.FaxNo, "</b><br /><b>E-mail id </b>: <a style='color:#df012a;' href='mailto:", signature.GeneralEmail, "'>", "bgv.reports@securitas-india.com", "</a>");
            }

            From = signature.GeneralEmail;
            DisplayName = signature.CompanyName.Trim();

            ClientCustomize cc = new ClientCustomize();
            DataSet ds = new DataSet();
            ds = cc.getAlertMailingForCaseRegister(CompanyRefNo1);
            if (ds.Tables.Count > 0)
            {
                if (ds.Tables[0].Rows.Count > 0)
                {
                    string body = string.Empty;
                    string MailSubject = string.Empty;

                    var templateDB = cc.getAlertMailtemplate(clientRowid, "Case Register", PackageId, MailType, "CaseRegisterTemplate");
                    if (templateDB.Rows.Count > 0)
                    {
                        body = Convert.ToString(templateDB.Rows[0]["MailTemplate"]);
                        MailSubject = Convert.ToString(templateDB.Rows[0]["MailSubject"]);
                    }

                    //using (StreamReader reader = new StreamReader(Server.MapPath("~/Emailers/Company/CaseRegisterTemplate.html")))
                    //{
                    //    body = reader.ReadToEnd();
                    //}
                    string CandidateName = Convert.ToString(ds.Tables[0].Rows[0]["CandidateName"]);
                    string CompanyRefNo = Convert.ToString(ds.Tables[0].Rows[0]["CompanyRefNo"]);
                    string CandidateEmail = Convert.ToString(ds.Tables[0].Rows[0]["candidateEmailId"]);
                    body = body.Replace("{FCandidateName}", CandidateName);
                    body = body.Replace("{FRefNo}", CompanyRefNo);
                    body = body.Replace("{FCandidateEmail}", CandidateEmail);
                    body = body.Replace("{MailSignature}", MailSignature);
                    string Subject = " Case Register for " + CandidateName + "  " + CompanyRefNo;
                    string To = SpocEmailID + "," + ClientSpocEmailID;
                    if (To.Substring(To.Length - 1) == ",")
                        To = To.Substring(0, To.Length - 1);
                    bool flag = false;
                    if (clientRowid == 257)
                    {
                        string bcc = "";
                        string Ccc = "";
                        Ccc = SpocEmailID;
                        bcc = ClientSpocEmailID;
                        flag = mail.SendMail(DisplayName, From, Ccc, "", bcc, Subject, body);

                    }
                    else
                    {
                        flag = mail.SendMail_Report(DisplayName, From, To, Subject, body);
                    }


                    if (flag)
                    {
                        result = true;
                    }
                    else
                    {
                        TempData["ErrorMsg"] = "Mail sending failed!";
                    }
                }
            }
            else
            {
                result = false;
            }
            return result;
        }


        bool SendAlertMassageAccessType2ForCaseRegister(string CompanyRefNo1, string ClientUserEmailID, string ReportingTo_EmailID, string AlertType = "", int PackageId = 0, int MailType = 0)
        {
            bool result = false;
            string MailSignature = string.Empty;
            string From = string.Empty;
            string DisplayName = string.Empty;
            string Cc = string.Empty; //Session["CSpocEmailID"].ToString();

            clsSendMail mail;
            mail = new clsSendMail();
            var signature = mail.GetCompanyMailSignature();

            if (signature != null)
            {
                MailSignature = string.Concat("For Securitas India. <br /><br />");
                MailSignature = string.Concat(MailSignature, "<b>", signature.CompanyName.Trim(), "</b><br /><b>Mobile: ", signature.MobileNo,
                    " | Direct Tel: ", signature.PhoneNo, " | Fax: ", signature.FaxNo, "</b><br /><b>E-mail id </b>: <a style='color:#df012a;' href='mailto:", signature.GeneralEmail, "'>", "bgv.reports@securitas-india.com", "</a>");
            }

            From = signature.GeneralEmail;
            DisplayName = signature.CompanyName.Trim();

            ClientCustomize cc = new ClientCustomize();
            DataSet ds = new DataSet();
            ds = cc.getAlertMailingForCaseRegister(CompanyRefNo1);
            if (ds.Tables.Count > 0)
            {
                if (ds.Tables[0].Rows.Count > 0)
                {
                    string body = string.Empty;
                    string MailSubject = string.Empty;
                    var clientid = Convert.ToInt32(ds.Tables[0].Rows[0]["ClientRowId"]);
                    var templateDB = cc.getAlertMailtemplate(clientid, AlertType, PackageId, MailType, "CaseRegisterTemplate");
                    if (templateDB.Rows.Count > 0)
                    {
                        body = Convert.ToString(templateDB.Rows[0]["MailTemplate"]);
                        MailSubject = Convert.ToString(templateDB.Rows[0]["MailSubject"]);
                    }

                    //using (StreamReader reader = new StreamReader(Server.MapPath("~/Emailers/Company/CaseRegisterTemplate.html")))
                    //{
                    //    body = reader.ReadToEnd();
                    //}
                    string CandidateName = Convert.ToString(ds.Tables[0].Rows[0]["CandidateName"]);
                    string CompanyRefNo = Convert.ToString(ds.Tables[0].Rows[0]["CompanyRefNo"]);

                    string CandidateEmail = Convert.ToString(ds.Tables[0].Rows[0]["candidateEmailId"]);
                    body = body.Replace("{FCandidateName}", CandidateName);
                    body = body.Replace("{FRefNo}", CompanyRefNo);
                    body = body.Replace("{FCandidateEmail}", CandidateEmail);

                    body = body.Replace("{MailSignature}", MailSignature);

                    string Subject = " Case Register for " + CandidateName + "  " + CompanyRefNo;
                    string To = ClientUserEmailID;
                    string ccc = ReportingTo_EmailID;


                    To = To.Replace(",", ";");
                    string[] arToMail = To.Split(';');
                    To = "";
                    foreach (string a in arToMail)
                    {
                        if (!To.Contains(a))
                        {
                            To = To + a.Trim() + ",";
                        }
                    }
                    //if (To.Length > 1)
                    //    To = To.Substring(0, To.Length - 1);


                    ccc = ccc.Replace(",", ";");
                    string[] arToMailcc = ccc.Split(';');
                    ccc = "";
                    foreach (string a in arToMailcc)
                    {
                        if (!ccc.Contains(a))
                        {
                            ccc = ccc + a.Trim() + ",";
                        }
                    }
                    //if (ccc.Length > 1)
                    //    ccc = ccc.Substring(0, ccc.Length - 1);

                    //if (ccc.Substring(ccc.Length - 1) == ",")
                    //    ccc = ccc.Substring(0, To.Length - 1);

                    bool flag = mail.SendMail(DisplayName, From, To, ccc, Subject, body);
                    if (flag)
                    {
                        result = true;
                    }
                    else
                    {
                        TempData["ErrorMsg"] = "Mail sending failed!";
                    }
                }
            }

            else
            {
                result = false;
            }
            return result;
        }

