                string ClientAccessType = Convert.ToString(Session["ClientAccessType"]);

                ViewBag.CheckStatus = CheckStatus;

                ViewBag.ErrorMsg = "";
                if (Search != "")
                {
                    if (clsCommonMethods.ValidateSQLInjuctionInput(Search) == false)
                    {
                        ViewBag.ErrorMsg = "Please Provide Valid Input";
                    }
                }
                if (ViewBag.ErrorMsg == "")
                {
                    if (ClientAccessType == "3" && ClientRowID > 0)
                    {
                        ClientUserRowID = ClientRowID;
                        ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
                        allClients = 0;
                        ViewBag.clientUserRowid = Convert.ToString(ClientUserRowID);
                        ViewBag.ClientRowID = clsCommonMethods.PEncrypt(Convert.ToString(ClientRowID));
                    }

                    if (ClientAccessType == "3" && ClientRowID == 0)
                    {
                        ClientUserRowID = Convert.ToInt16(Session["ClientUserRowID"]);
                        ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
                        allClients = 1;
                        ViewBag.clientUserRowid = Convert.ToString(ClientUserRowID);
                        ViewBag.ClientRowID = clsCommonMethods.PEncrypt(Convert.ToString(ClientRowID));
                    }

                    if (ClientAccessType == "2" && ClientRowID > 0)
                    {
                        ClientUserRowID = Convert.ToInt32(Session["ClientUserRowID"]);
                        allClients = 0;
                        ViewBag.clientUserRowid = Convert.ToString(ClientUserRowID);
                        ViewBag.ClientRowID = clsCommonMethods.PEncrypt(Convert.ToString(ClientRowID));
                    }

                    if (ClientAccessType == "2" && ClientRowID == 0)
                    {
                        ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
                        ClientUserRowID = Convert.ToInt32(Session["ClientUserRowID"]);
                        allClients = 1;
                        ViewBag.clientUserRowid = Convert.ToString(ClientUserRowID);
                        ViewBag.ClientRowID = clsCommonMethods.PEncrypt(Convert.ToString(ClientRowID));
                    }

                    if (ClientAccessType == "1")
                    {
                        ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
                        ClientUserRowID = Convert.ToInt32(Session["ClientUserRowID"]);
                        allClients = 1;
                        ViewBag.clientUserRowid = Convert.ToString(ClientUserRowID);
                        ViewBag.ClientRowID = clsCommonMethods.PEncrypt(Convert.ToString(ClientRowID));
                    }
                    model = repoEmploymentInfo.GetAllYTRChecksListForDETL1(page, pageSize, sort.ToLower(), sortDir.ToLower(), Search, ClientRowID, RecievingToDate, RecievingFromDate, CompletedToDate, CompletedFromDate, "", CheckStatus, ClientUserRowID, allClients);
                }
                PQPersonalSearchPagedModel SearchModel = new PQPersonalSearchPagedModel();
                SearchModel.Search = Search;
                SearchModel.RecievingFromDate = RecievingFromDate;
                SearchModel.CompletedFromDate = CompletedFromDate;
                SearchModel.RecievingToDate = RecievingToDate;
                SearchModel.CompletedToDate = CompletedToDate;
                model.ItemSearch = SearchModel;

            }
            catch (Exception Ex)
            {
                //ViewBag.ErrorMsg = Ex.Message;
                ViewBag.ErrorMsg = "Invalid paramerter value";
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }
            return View(model);
        }

        [HttpGet]
        [SessionExpireFilterAttributeClient]
        [ValidateInput(false)]
        public ActionResult EmploymentYTRChecksClearByClient(string id = "", string SubCheckRowID = "", string CheckFamilyRowID = "")
        {
            PQEmploymentYTRClearViewModel model = new PQEmploymentYTRClearViewModel();
            int Did = 0;
            if (id != "")
            {
                Did = Convert.ToInt32(HttpUtility.UrlDecode(clsCommonMethods.PDecrypt(id)));

            }
            short SubCheckId = Convert.ToInt16(clsCommonMethods.PDecrypt(SubCheckRowID));
            int CheckFamilyId = Convert.ToInt32(clsCommonMethods.PDecrypt(CheckFamilyRowID));
            try
            {
                if (Did > 0)
                {
                    ClientCustomize cc = new ClientCustomize();
                    DataTable dt = cc.GetCheckDetails(Did);
                    if (dt.Rows.Count > 0)
                    {
                        model.PersonalRowID = Convert.ToInt32(dt.Rows[0]["Personalrowid"].ToString());
                        model.ClientRowId = Convert.ToInt32(dt.Rows[0]["ClientRowId"].ToString());
                    }
                    //=============
                    ClientCustomize CC1 = new ClientCustomize();
                    DataTable dtx = new DataTable();
                    dtx = CC1.GetClientLWDRequired(model.ClientRowId);
                    bool dolisrequired = true;
                    if (dtx.Rows.Count > 0)
                    {
                        dolisrequired = Convert.ToBoolean(dtx.Rows[0]["DOLIsRequired"]);
                        if (dolisrequired)
                        {
                            dolisrequired = true;
                        }
                        else
                        {
                            dolisrequired = false;

                        }
                    }

                    //============
                    model.EmploymentRowID = Did;
                    model.CheckFamilyRowID = CheckFamilyId;
                    model.SubCheckRowID = SubCheckId;
                    model.DOLisRequired = dolisrequired;
                    Session["ClientRowID"] = model.ClientRowId;
                }
                else
                {
                    ViewBag.ErrorMsg = "Invalid Id!";
                }
            }
            catch (Exception Ex)
            {
                //ViewBag.ErrorMsg = Ex.Message;
                ViewBag.ErrorMsg = "Invalid paramerter value";
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }
            return View(model);
        }
