        [HttpGet]
        [SessionExpireFilterAttributeClient]
        public async Task<JsonResult> ClientCaseApproveByID(int id = 0) /*, string DOJ = "", string clientrowid = ""*/
        {
            //if(clientrowid == "992" || clientrowid == "993" || clientrowid == "994" || clientrowid == "1125" || clientrowid == "1243")
            //{
            //    ClientCustomize ccc = new ClientCustomize();
            //    ccc.AddUpdateDoj(id, DOJ);
            //}
            DataBaseConnections DC = new DataBaseConnections();
            TempPQCandidateCheck tpc = new TempPQCandidateCheck();
            bool result = false;
            //bool importResult = false;
            int count = 0;
            try
            {
                if (id > 0)
                {
                    int createdBy = 0;
                    createdBy = int.Parse(Convert.ToString(Session["ClientUserRowID"]));
                    string strResult = tpc.ApproveOrFinalSubmitByCandidate(id, createdBy);
                    string ClientRowID = Session["ClientRowID"].ToString();
                    if (strResult == "Success")
                    {
                        result = true;
                        if(ClientRowID=="1606" || ClientRowID == "684")
                        {                           
                           var Pdt= DC.GetPersonalDetailsForPersistantClient(id);
                            if(Pdt.Rows.Count>0)
                            {
                                int PersonalRowId = Convert.ToInt32(Pdt.Rows[0]["PersonalRowID"]);
                                string LJsonString= Convert.ToString(Pdt.Rows[0]["JsonString"]);
                                if(LJsonString!="")
                                {
                                    LivenessRoot model = JsonConvert.DeserializeObject<LivenessRoot>(LJsonString);
                                    double faceMatchScore = model.result.apiResponse.result.faceMatchScore;
                                    double livenessScore = model.result.apiResponse.result.livenessScore;
                                    bool isFaceMatch = model.result.apiResponse.result.isFaceMatch;
                                    if (faceMatchScore > 60) 
                                    {
                                        if (livenessScore > 60)
                                        {
                                            var rst = cc.UpdateCandidateChecksReportComments(PersonalRowId, 890);
                                            cc.UpdatePQCandidateChecksColorCode(0, 6, "Green", PersonalRowId, 890, "Verified");
                                            cc.UpdateCheckStatus(PersonalRowId, 890, 1, 37, "Check", 152);
                                            DC.UpdatelivenessChecktbldataEntryData(PersonalRowId,890, "Positive");
                                        }
                                        else
                                        {
                                            var rst = cc.UpdateCandidateChecksReportComments(PersonalRowId, 890);
                                            cc.UpdatePQCandidateChecksColorCode(248, 1, "Red", PersonalRowId, 890, "Liveness failed");
                                            cc.UpdateCheckStatus(PersonalRowId, 890, 1, 37, "Check", 152);
                                            DC.UpdatelivenessChecktbldataEntryData(PersonalRowId, 890, "Negative");
                                        }
                                    }
                                    else
                                    {
                                        var rst = cc.UpdateCandidateChecksReportComments(PersonalRowId, 890);
                                        cc.UpdatePQCandidateChecksColorCode(248, 1, "Red", PersonalRowId, 890, "Face Match failed");
                                        cc.UpdateCheckStatus(PersonalRowId, 890, 1, 37, "Check", 152);
                                        DC.UpdatelivenessChecktbldataEntryData(PersonalRowId, 890, "Negative");
                                    }
                                }                                
                            }

                        }

                        if (ClientRowID == "1749")
                        {

                            var Pdt = DC.GetPersonalDetailsForPersistantClient(id);
                            if (Pdt.Rows.Count > 0)
                            {
                                int PersonalRowId = Convert.ToInt32(Pdt.Rows[0]["PersonalRowID"]);
                                new API().UpdateAPICheckStatus(ClientRowID.ToString(), Convert.ToInt32(PersonalRowId), 0, "WIP");
                            }

                        }
                        await MoveLOADocUploadedByCandidate(id);
                        //SendMail(ids, ClientRowID);
                        new API().UpdateAPINewCaseInitiateStatus(id, ClientRowID, "ClientCaseApprove");
                        if (ClientRowID == "992" || ClientRowID == "993" || ClientRowID == "994" || ClientRowID == "1125" || ClientRowID == "1243")
                        {
                            string CaseApproveRejectFlag = System.Configuration.ConfigurationManager.AppSettings["CaseApproveRejectFlag"].ToString();
                            if(CaseApproveRejectFlag == "1")
                            {
                                string msg = "";
                                #region Send Mail To Candidate
                                if (!string.IsNullOrEmpty(id.ToString()))
                                {
                                    string spocEmail = "";
                                    string cSpocEmail = "";
                                    string mobileno = "";

                                    string TrmFldPathDoc = "";
                                    string fileName = "";




