        [HttpPost]
        [SessionExpireFilterAttributeClient]
        public async Task<JsonResult> ClientCaseApproveByHRID(int id = 0, string remark = "")
        {
            TempPQCandidateCheck tpc = new TempPQCandidateCheck();
            bool result = false;
            int count = 0;

            try
            {
                if (id > 0)
                {
                    ClientCustomize cc = new ClientCustomize();
                    string ClientRowID = Session["ClientRowID"].ToString();
                    int createdBy = int.Parse(Convert.ToString(Session["ClientUserRowID"]));

                    // Save uploaded files
                    if (ClientRowID == "684" && Request.Files.Count > 0)
                    {
                        string path = ConfigurationManager.AppSettings["provideddocuments"];
                        for (int i = 0; i < Request.Files.Count; i++)
                        {
                            var file = Request.Files[i];
                            if (file != null && file.ContentLength > 0)
                            {
                                var fileName = Path.GetFileName(file.FileName);
                                string base64 = string.Empty;
                                file.InputStream.Position = 0;
                                using (var memoryStream = new MemoryStream())
                                {
                                    file.InputStream.CopyTo(memoryStream); // Convert the byte array to Base64 
                                    base64 = Convert.ToBase64String(memoryStream.ToArray());
                                }
                                _documentService.UploadDynamicCandidateFiles(file.FileName, base64, "D:/wwwroot2/Documents/CandidateDocuments/ProvidedDocuments/");
                                //var savePath = Server.MapPath(path + fileName);
                                //file.SaveAs(savePath);
                                cc.proc_InsertUpdateTempPQVerifiedUploadCaseDocsHRApproval(id, fileName, path, "HR Approval", "Provided", remark);
                            }
                        }

                        // Save or log remarks (if needed)
                        // You can save `remark` to DB here based on your logic
                    }

                    string strResult = tpc.ApproveOrFinalSubmitByCandidate(id, createdBy);
                    if (strResult == "Success")
                    {
                        result = true;
                        if (ClientRowID == "684")
                        {
                            DataBaseConnections DC = new DataBaseConnections();
                            var Pdt = DC.GetPersonalDetailsForPersistantClient(id);
                            if (Pdt.Rows.Count > 0)
                            {
                                int PersonalRowId = Convert.ToInt32(Pdt.Rows[0]["PersonalRowID"]);
                                string LJsonString = Convert.ToString(Pdt.Rows[0]["JsonString"]);
                                if (LJsonString != "")
                                {
                                    LivenessRoot model = JsonConvert.DeserializeObject<LivenessRoot>(LJsonString);
                                    double faceMatchScore = model.result.apiResponse.result.faceMatchScore;
                                    double livenessScore = model.result.apiResponse.result.livenessScore;
                                    bool isFaceMatch = model.result.apiResponse.result.isFaceMatch;
                                    if (faceMatchScore > 70)
                                    {
                                        if (livenessScore > 70)
                                        {
                                            var rst = cc.UpdateCandidateChecksReportComments(PersonalRowId, 890);
                                            cc.UpdatePQCandidateChecksColorCode(0, 6, "Green", PersonalRowId, 890, "Verified");
                                            cc.UpdateCheckStatus(PersonalRowId, 890, 1, 37, "Check", 152);
                                            DC.UpdatelivenessChecktbldataEntryData(PersonalRowId, 890, "Positive");
                                        }
                                        else
                                        {
                                            var rst = cc.UpdateCandidateChecksReportComments(PersonalRowId, 890);
                                            cc.UpdatePQCandidateChecksColorCode(248, 1, "Red", PersonalRowId, 890, "Liveness failed");
                                            cc.UpdateCheckStatus(PersonalRowId, 890, 1, 37, "Check", 152);
                                            DC.UpdatelivenessChecktbldataEntryData(PersonalRowId, 890, "Negative");
                                        }
                                    }
                                    else
                                    {
                                        var rst = cc.UpdateCandidateChecksReportComments(PersonalRowId, 890);
                                        cc.UpdatePQCandidateChecksColorCode(248, 1, "Red", PersonalRowId, 890, "Face Match failed");
                                        cc.UpdateCheckStatus(PersonalRowId, 890, 1, 37, "Check", 152);
                                        DC.UpdatelivenessChecktbldataEntryData(PersonalRowId, 890, "Negative");
                                    }
                                }

                            }

                        }
                        await MoveLOADocUploadedByCandidate(id);



                        new API().UpdateAPINewCaseInitiateStatus(id, ClientRowID, "ClientCaseApprove");
                    }
                    else
                    {
                        ViewBag.ErrorMsg = strResult;
                    }
                }
                else
                {
                    ViewBag.ErrorMsg = "Invalid Id!";
                }
            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = "Invalid parameter value";
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }

            return Json(new { result, count });
        }
