        [HttpGet]
        [SessionExpireFilterAttributeClient]
        [ValidateInput(false)]
        public ActionResult FundPendingApproveByClient(string PersonalId = "", string VerId = "", string chkFmlyId = "", string SubchkFmlyId = "", string msg = "")
        {
            if (msg != "")
            {
                ViewBag.ErrorMsg = msg;
            }
            int perId = Convert.ToInt32(clsCommonMethods.PDecrypt(PersonalId));
            int VerificationId = Convert.ToInt32(clsCommonMethods.PDecrypt(VerId));
            short CheckFamilyId = Convert.ToInt16(clsCommonMethods.PDecrypt(chkFmlyId));
            short subCheckId = Convert.ToInt16(clsCommonMethods.PDecrypt(SubchkFmlyId));
            FundPendingApprovalViewModel model = new FundPendingApprovalViewModel();
            ClientCustomize cc = new ClientCustomize();
            try
            {

                DataTable dt;
                dt = cc.GetsFundsPendingAmount(perId, subCheckId);
                if (dt.Rows.Count > 0)
                {
                    model.Amount = Convert.ToDecimal(dt.Rows[0]["Amount"].ToString());
                    model.Remarks = dt.Rows[0]["Remarks"].ToString();
                    ViewBag.EducationQualification = dt.Rows[0]["EduQualification"] != DBNull.Value ? dt.Rows[0]["EduQualification"].ToString() : "";
                }


                if (perId > 0 && VerificationId > 0 && CheckFamilyId > 0 && subCheckId > 0)
                {
                    model.PersonalRowID = perId;
                    model.VerificationRowID = VerificationId;
                    model.CheckFamilyRowID = CheckFamilyId;
                    model.SubCheckRowID = subCheckId;
                }
                else
                {
                    if (perId > 0 && subCheckId > 0)
                    {
                        model.PersonalRowID = perId;
                        model.SubCheckRowID = subCheckId;
                        model.CheckFamilyRowID = CheckFamilyId;
                    }
                }
            }
            catch (Exception ex)
            {
                ViewBag.ErrorMsg = "Error Found !.";
                string ErrorMessage = ViewBag.ErrorMsg ;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), ex.Message, ex.StackTrace);
                return RedirectToAction("ExceptionPage", "Home", new { area = "ClientArea", ClientRowId = "", msg = ErrorMessage });
            }
            return View(model);
        }

        [HttpPost]
        [ValidateAntiForgeryToken]
        [ValidateInput(false)]
        public ActionResult FundPendingApproveByClient(FundPendingApprovalViewModel model)
        {
            try
            {
                if (ModelState.IsValid)
                {
                    ClientCustomize cc = new ClientCustomize();
                    DataTable dt;
                    string QCRemark = "";
                    dt = cc.GetsFundsPendingAmount(model.PersonalRowID, model.SubCheckRowID);
                    if (dt.Rows.Count > 0)
                    {
                        model.Amount = Convert.ToDecimal(dt.Rows[0]["Amount"].ToString());
                        model.ExpectedTat = Convert.ToString(dt.Rows[0]["ExpectedTAT"].ToString());
                        QCRemark = dt.Rows[0]["Remarks"].ToString();
                    }
                    string BothRemark = "(funds request " + model.FundsStatus + " By client ) Qc Remark: " + QCRemark + " , Client Remark= " + model.Remarks + "";
                    if (model.PersonalRowID > 0 && model.VerificationRowID > 0 && model.CheckFamilyRowID > 0 && model.SubCheckRowID > 0)
                    {
                        short ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
                        model.CheckStatus = "WIP-Pending";
                        model.ModifiedBy = ClientRowID;
                        model.ModifiedDate = DateTime.Now;
                        repoVerificationInfo.FundPendingChecksUpdateByDepartmentTL(model);

                        #region Check Action History Save                           
                        clsCommonMethods.AddCheckActionHistoryByClient(model.PersonalRowID, model.SubCheckRowID, model.CheckStatus, model.Remarks);
                        #endregion

                        cc.Process_Remarks_Insert(model.PersonalRowID, model.SubCheckRowID, 61, model.Remarks, "Client", Convert.ToInt16(Session["ClientRowID"]));
                        cc.UpdateCheckStatus(model.PersonalRowID, model.SubCheckRowID, 1, 61, "Client", Convert.ToInt16(Session["ClientRowID"]));
                        cc.InsertFundsAmount(model.PersonalRowID, model.SubCheckRowID, model.Amount, BothRemark, Session["ClientRowID"].ToString(), Session["ClientRowID"].ToString(), model.FundsStatus, model.ExpectedTat);
                        ModelState.Clear();
                        ViewBag.SuccessMsg = "Record Updated Successfully!";

                        //TempData["SuccessMsg"] = "Record Updated Successfully!";
                        //RedirectToAction("ManageFundPendingChecksForDeprtTL");
                    }
                    else
                    {
                        if (model.PersonalRowID > 0 && model.SubCheckRowID > 0)
                        {

                            if (model.FundsStatus == "Reject")
                            {
                                // 60 check status for funds request Reject by client
                                cc.Process_Remarks_Insert(model.PersonalRowID, model.SubCheckRowID, 61, model.Remarks, "Client", Convert.ToInt16(Session["ClientRowID"]));
                                cc.UpdateCheckStatus(model.PersonalRowID, model.SubCheckRowID, 1, 61, "Client", Convert.ToInt16(Session["ClientRowID"]));
                                cc.InsertFundsAmount(model.PersonalRowID, model.SubCheckRowID, model.Amount, BothRemark, Session["ClientRowID"].ToString(), Session["ClientRowID"].ToString(), model.FundsStatus, model.ExpectedTat);

                                repoPQCandidateCheck.UpdateFundDateandRemark(model.PersonalRowID, model.SubCheckRowID, "Reject", model.Remarks);

                                #region Check Action History Save                           
                                clsCommonMethods.AddCheckActionHistoryByClient(model.PersonalRowID, model.SubCheckRowID, "Fund Rejected", model.Remarks);
                                #endregion
                                SendAlertMassageForFundApprovalMail(model.PersonalRowID, model.SubCheckRowID, model.Remarks, "REJECTED", "Funds Approval", 0, 1);
                                ModelState.Clear();
                                ViewBag.SuccessMsg = "Record Updated Successfully!";
                            }
                            else
                            {
                                // 61 check status for funds request closed by client
                                cc.Process_Remarks_Insert(model.PersonalRowID, model.SubCheckRowID, 61, model.Remarks, "Client", Convert.ToInt16(Session["ClientRowID"]));
                                cc.UpdateCheckStatus(model.PersonalRowID, model.SubCheckRowID, 1, 61, "Client", Convert.ToInt16(Session["ClientRowID"]));
                                cc.InsertFundsAmount(model.PersonalRowID, model.SubCheckRowID, model.Amount, BothRemark, Session["ClientRowID"].ToString(), Session["ClientRowID"].ToString(), model.FundsStatus, model.ExpectedTat);

                                repoPQCandidateCheck.UpdateFundDateandRemark(model.PersonalRowID, model.SubCheckRowID, "Approve", model.Remarks);

                                #region Check Action History Save                           
                                clsCommonMethods.AddCheckActionHistoryByClient(model.PersonalRowID, model.SubCheckRowID, "Fund Approved", model.Remarks);
                                #endregion
                                //SendAlertMassageForFundApproval(model.PersonalRowID, model.SubCheckRowID,model.Remarks);
                                SendAlertMassageForFundApprovalMail(model.PersonalRowID, model.SubCheckRowID, model.Remarks, "APPROVED", "Funds Approval", 0, 1);
                                ModelState.Clear();
                                ViewBag.SuccessMsg = "Record Updated Successfully!";
                            }
                        }
                        else
                            ViewBag.ErrorMsg = "All fields are mandatory!";
                    }
                }
                else
                {
                    var query = from state in ModelState.Values
                                from error in state.Errors
                                select error.ErrorMessage;
                    var errorList = query.ToList();
                    string strError = string.Empty;
                    foreach (string str in errorList)
                    {
                        strError += str + "\n";
                    }
                    ModelState.AddModelError("", strError);
                }
            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = "Error Found !.";
                string ErrorMessage = ViewBag.ErrorMsg ;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
                return RedirectToAction("FundPendingApproveByClient", "Home", new { area = "ClientArea", PersonalId = clsCommonMethods.PEncrypt(model.PersonalRowID.ToString()), VerId = clsCommonMethods.PEncrypt(model.VerificationRowID.ToString()), chkFmlyId = clsCommonMethods.PEncrypt(model.CheckFamilyRowID.ToString()), SubchkFmlyId = clsCommonMethods.PEncrypt(model.SubCheckRowID.ToString()), msg = ErrorMessage });
            }
            return View(model);
        }

