        [HttpPost]
        [SessionExpireFilterAttributeClient]
        [ValidateAntiForgeryToken]
        [ValidateInput(false)]
        public ActionResult UploadCandidateDocumentByHr(AddUploadDocByHRViewModel model, string UploadHid, IEnumerable<HttpPostedFileBase> UploadDoc)
        {
            try
            {
                if (ModelState.IsValid)
                {
                    if (model.PersonalRowID > 0 && !string.IsNullOrEmpty(UploadHid) && UploadDoc != null && UploadDoc.FirstOrDefault() != null && UploadDoc.FirstOrDefault().ContentLength > 0)
                    {
                        int count = 0;
                        string[] DocumentTypes = UploadHid.Split(',');
                        foreach (var item in UploadDoc)
                        {
                            model.FileName = model.FileName;
                            model.DocumentType = DocumentTypes[count];
                            if (model.DocumentType != null && model.FileName != null && item.ContentLength > 0)
                            {
                                SavePQVerifiedUploadDoc(model.VerifiedUploadRowID, model.PersonalRowID, model.SubCheckRowID, "Provided", model.DocumentType, "provideddocuments", item, model.Remarks, model.FileName);
                            }
                            else
                            {
                                ViewBag.ErrorMsg = "No item found!";
                                break;
                            }
                            count++;
                        }
                        //CreateMenuitemforDataEntryOperator(model.PersonalRowID);
                        //int PID = model.PersonalRowID;
                        TempData["SuccessMsg"] = "Record Added Successfully!";
                        ModelState.Clear();
                        return RedirectToAction("ManageUploadDocmentList", "Home", new { area = "ClientArea", pid = model.PersonalRowID });
                    }
                    else
                    {
                        ViewBag.ErrorMsg = "Please select document!";
                    }
                }
                else
                {
                    var query = from state in ModelState.Values
                                from error in state.Errors
                                select error.ErrorMessage;

                    var errorList = query.ToList();
                    string strError = string.Empty;
                    foreach (string str in errorList)
                    {
                        strError += str + "\n";
                    }
                    ModelState.AddModelError("", strError);
                }
            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = "Error Found !.";
                string ErrorMessage = ViewBag.ErrorMsg ;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
                return RedirectToAction("UploadCandidateDocumentByHr", "Home", new { area = "ClientArea", id = model.VerifiedUploadRowID, pid = model.PersonalRowID, SubCheckRowID = model.SubCheckRowID, FileName = "", msg = ErrorMessage });
            }

            return View(model);
        }
