        [NonAction]
        private async Task<int> MoveLOADocUploadedByCandidate(int PersonalRowId)
        {
            try
            {
                string existFile = repoPQPersonal.GetPQPersonalCaseDocUploadedByCandidate(PersonalRowId);
                if (!string.IsNullOrEmpty(existFile))
                {
                    string FldPathDoc = ConfigurationManager.AppSettings["CandidateSignAgreeDoc"].ToString();
                    string FldMovePathDoc = ConfigurationManager.AppSettings["provideddocuments"].ToString();
                    //string path = Server.MapPath(FldPathDoc + existFile);
                    //FileInfo file = new FileInfo(path);
                    //if (file.Exists)//check file exsit or not
                    //{
                    //    file.MoveTo(Server.MapPath(FldMovePathDoc + existFile));
                    //}
                    //=====================================
                    if (FldPathDoc.StartsWith("~/"))
                    {
                        FldPathDoc = FldPathDoc.Replace("~/", @"D:/wwwroot2/");
                    }
                    if (FldPathDoc.StartsWith("/"))
                    {
                        FldPathDoc = @"D:/wwwroot2/" + FldPathDoc.Substring(1);
                    }
                    HttpResponseMessage response1 = await _documentService.GetDocumentAsync(existFile, FldPathDoc);


                    if (response1.IsSuccessStatusCode)
                    {
                        var jsonString = await response1.Content.ReadAsStringAsync();
                        var obj = JsonConvert.DeserializeObject<DocumentResponse>(jsonString);

                        string docName = obj.DocumentName;
                        string base64Data = obj.DocumentValue;

                        if (FldMovePathDoc.StartsWith("~/"))
                        {
                            FldMovePathDoc = FldMovePathDoc.Replace("~/", @"D:/wwwroot2/");
                        }
                        if (FldMovePathDoc.StartsWith("/"))
                        {
                            FldMovePathDoc = @"D:/wwwroot2/" + FldMovePathDoc.Substring(1);
                        }

                        _documentService.UploadDynamicCandidateFiles(docName, base64Data, FldMovePathDoc);
                    }
                    //===========================================
                    
                }
            }
            catch (Exception)
            {
                throw;
            }
            return 1;
        }

