        public JsonResult GetChecksAndPackageByClientId(short id = 0, byte pt = 0, string Des = null, string Entity = null)
        {
            //Package" = "1"    Check"   = "2"   Both"    = "3"  
            if (id > 0)
            {
                var allData = repoPQClient.GetChecksAndPackageByClientId(id, pt);
                if (allData != null)
                {
                    if (id == 797 || id == 791 || id == 792 || id == 793 || id == 794 || id == 795 || id == 796)
