                                if (Des.Replace(" ", "").ToLower() == "seniorsalesmanager" || Des.Replace(" ", "").ToLower() == "salesmanager" || Des.Replace(" ", "").ToLower() == "salesofficer" || Des.Replace(" ", "").ToLower() == "seniorsalesofficer")
