        public async Task<int> SavePQVerifiedUploadCaseDoc(int PersonalRowID = 0, string DocumentUploadFrom = "", string DocumentType = "", string FolderNameForSave = "", HttpPostedFileBase UploadDoc = null, string remarks = "", bool NADoc = false)
        {
            try
            {
                string secRefId = PersonalRowID.ToString();
                AddPQVerifiedUploadCaseDocViewModel DocModel = new AddPQVerifiedUploadCaseDocViewModel();
                DocModel.PersonalRowID = PersonalRowID;
                DocModel.DocumentUploadFrom = DocumentUploadFrom; //  Provided / Verified
                DocModel.DocumentType = DocumentType; //Name of the selected docs
                if (!NADoc)
                {
                    string FileName = (secRefId + " " + UploadDoc.FileName.Split('.')[0] + "_" + DateTime.Now.ToString()).Replace(" ", "_").Replace("-", "_").Replace(":", "_").Replace("/", "_");
                    if (FileName.Contains("24/7CPL_"))
                    {
                        FileName = FileName.Replace("/", "-");
                    }
                    string FldPathDoc = string.Empty;
                    FldPathDoc = ConfigurationManager.AppSettings[FolderNameForSave.Trim().ToLower()].ToString();

                    string existFile = repoPQVerifiedUploadCaseDoc.ExistcaseFileByPersonalIdAndDocType(PersonalRowID, DocumentType, FileName);
                    if (!string.IsNullOrEmpty(existFile))
                    {

                        if (FldPathDoc.StartsWith("~/"))
                        {
                            FldPathDoc = FldPathDoc.Replace("~/", @"D:/wwwroot2/");
                        }
                        if (FldPathDoc.StartsWith("/"))
                        {
                            FldPathDoc = @"D:/wwwroot2/" + FldPathDoc.Substring(1);
                        }
                        HttpResponseMessage response1 = await _documentService.GetDocumentAsync(existFile, FldPathDoc);


                        if (response1.IsSuccessStatusCode)
                        {
                            var jsonString = await response1.Content.ReadAsStringAsync();
                            var obj = JsonConvert.DeserializeObject<DocumentResponse>(jsonString);

                            string docName = obj.DocumentName;
                            string base64Data = obj.DocumentValue;
                            await _documentService.DeleteDocumentAsync(existFile, FldPathDoc);
                        }



                        //string path = Server.MapPath(FldPathDoc + existFile);
                        //FileInfo file = new FileInfo(path);
                        //if (file.Exists)//check file exsit or not
                        //{
                        //    file.Delete();
                        //}
                    }
                    string proImg = string.Empty;
                    string ext = Path.GetExtension(UploadDoc.FileName).ToLower();
                    proImg = FileName + ext;

                    string base64N = string.Empty;
                    UploadDoc.InputStream.Position = 0;
                    using (var memoryStream = new MemoryStream())
                    {
                        UploadDoc.InputStream.CopyTo(memoryStream); // Convert the byte array to Base64 
                        base64N = Convert.ToBase64String(memoryStream.ToArray());
                    }
                    _documentService.UploadDynamicCandidateFiles(proImg, base64N, "D:/wwwroot2/Documents/CandidateDocuments/ProvidedDocuments/");

               //     UploadDoc.SaveAs(Server.MapPath(FldPathDoc + proImg));
                    DocModel.FileName = Path.GetFileName(proImg);
                    DocModel.FilePath = FldPathDoc;
                }
                else
                {
                    DocModel.FileName = "NA";
                    DocModel.FilePath = "NA";
                }
                DocModel.UploadDate = DateTime.Now;
                DocModel.Status = 1;
                DocModel.Remarks = remarks;
                repoPQVerifiedUploadCaseDoc.AddPQVerifiedUploadCaseDoc(DocModel);
                repoPQVerifiedUploadCaseDoc.SaveChanges();
                return 1;
            }
            catch (Exception Ex)
            {
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }
            return 1;
        }



        public void SavePQVerifiedUploadDoc(Int64 VerifiedUploadRowID = 0, int PersonalRowID = 0, short SubCheckRowID = 0, string DocumentUploadFrom = "", string DocumentType = "", string FolderNameForSave = "", HttpPostedFileBase UploadDoc = null, string remarks = "", string FileName = "")
        {
            try
            {
                AddUploadDocByHRViewModel DocModel = new AddUploadDocByHRViewModel();
                DocModel.VerifiedUploadRowID = VerifiedUploadRowID;
                DocModel.PersonalRowID = PersonalRowID;
