        [SessionExpireFilterAttributeClient]
        public async Task<ActionResult> GetAllReport(string ImageName, string ReportType)
        {
            ReportType = clsCommonMethods.PDecrypt(ReportType);
            string imgname = clsCommonMethods.PDecrypt(ImageName);

            ClientCustomize cc = new ClientCustomize();
            int ClientUserID = Convert.ToInt32(Session["ClientUserRowID"]);
            int clientid = Convert.ToInt32(Session["ClientRowID"]);

            DataTable ddt = cc.getAutoExistCompRefNo(imgname);

            // 1. Pura ZIP file memory me rakhne k liye stream banayi
            using (var memoryStream = new MemoryStream())
            {
                // 2. zipArchive ko sahi se initialize kiya loop se pehle
                using (var zipArchive = new ZipArchive(memoryStream, ZipArchiveMode.Create, true))
                {
                    if (ddt != null && ddt.Rows.Count > 0)
                    {
                        for (int i = 0; i < ddt.Rows.Count; i++)
                        {
                            string FldPathDoc = System.Configuration.ConfigurationManager.AppSettings["CandidateReportdoc"].ToString();
                            string CandidateOldReportPath = System.Configuration.ConfigurationManager.AppSettings["CandidateOldReportPath"].ToString();

                            string reportFileName = ddt.Rows[i]["ReportFileName"].ToString();
                            string type = ddt.Rows[i]["ReportType"].ToString();

                            if (FldPathDoc.StartsWith("~/"))
                            {
                                FldPathDoc = FldPathDoc.Replace("~/", @"D:/wwwroot2/");
                            }
                            else if (FldPathDoc.StartsWith("/"))
                            {
                                FldPathDoc = @"D:/wwwroot2/" + FldPathDoc.Substring(1);
                            }
                            FldPathDoc = FldPathDoc + reportFileName;

                            DataTable reportSecurity = cc.ReportSeurityBYdatabase(Convert.ToInt16(Session["ClientRowID"]), imgname);

                            string directoryPath = Path.GetDirectoryName(FldPathDoc) + Path.DirectorySeparatorChar;
                            string fileName = Path.GetFileName(FldPathDoc);


                            //string apiFileName = fileName + "_" + type;

                            HttpResponseMessage response = await _documentService.GetDocumentAsync(fileName, directoryPath);

                            if (response.IsSuccessStatusCode)
                            {
                                var jsonString = await response.Content.ReadAsStringAsync();
                                var obj = JsonConvert.DeserializeObject<DocumentResponse>(jsonString);

                                string docName = obj.DocumentName;
                                string base64Data = obj.DocumentValue;

                                byte[] fileBytes = Convert.FromBase64String(base64Data);

                                if (fileBytes != null && fileBytes.Length > 0)
                                {
                                    string fileNameSS = Path.GetFileNameWithoutExtension(FldPathDoc);
                                    string fileName1 = fileNameSS + "_" + type + ".pdf";


                                    var zipEntry = zipArchive.CreateEntry(fileName1, CompressionLevel.Fastest);
                                    using (var entryStream = zipEntry.Open())
                                    {

                                        await entryStream.WriteAsync(fileBytes, 0, fileBytes.Length);
                                    }
                                }
                            }
                        }
                    }
                }

                if (memoryStream.Length > 0)
                {
                    memoryStream.Position = 0;


                    string zipFileName = $"{imgname}.zip";
                    return File(memoryStream.ToArray(), "application/zip", zipFileName);
                }
            }


            return RedirectToAction("GetClientCasesDashBoardInfo", new { CaseStatus = "AllReportPerCase" });

            //return RedirectToAction("GetClientCasesDashBoardInfo", new { CaseStatus = "AllReportPerCase" });

        }
