        [HttpGet]
        public ActionResult CandidateDetailsPdf(string PID = "")
        {
            CadidateDetailPdfViewModels model = new CadidateDetailPdfViewModels();
            ClientCustomize cc = new ClientCustomize();
            DataTable dt = new DataTable();
            int PersonalRowID = 0;
            if (PID != "")
            {
                PersonalRowID = Convert.ToInt32(clsCommonMethods.PDecrypt(PID));
            }
            dt = cc.candidate_DetialsSearchpdf(Convert.ToInt32(PersonalRowID));
            Document pdfDoc = new Document(PageSize.A4, 25, 25, 50, 15);
            PdfWriter pdfWriter = PdfWriter.GetInstance(pdfDoc, Response.OutputStream);
            pdfDoc.Open();
            if (dt.Rows.Count > 0)
            {
                DataTable dt1 = new DataTable();
                if (PersonalRowID != 0)
                {
                    dt1 = cc.Getcandidate_DetialsSearchpdf(Convert.ToInt32(PersonalRowID));
                }
                PdfPTable table = new PdfPTable(5);
                table.WidthPercentage = 100;
                table.HorizontalAlignment = 0;
                table.SpacingBefore = 20f;
                table.SpacingAfter = 30f;

                string CreatedDate = Convert.ToDateTime(dt1.Rows[0]["CreatedDate"]).ToString("dd/MM/yyyy");
                PdfPCell cell = new PdfPCell(new Phrase("Created Date:- " + CreatedDate + "", FontFactory.GetFont("Times New Roman ,serif", 12)));
                cell.HorizontalAlignment = Element.ALIGN_RIGHT;
                cell.Border = 0;
                cell.Colspan = 5;
                table.AddCell(cell);
                pdfDoc.Add(table);

                table = new PdfPTable(5);
                table.WidthPercentage = 100;
                table.HorizontalAlignment = 0;
                table.SpacingBefore = 20f;
                table.SpacingAfter = 30f;

                cell = new PdfPCell();
                cell.Colspan = 5;
                cell.Border = 0;
                table.AddCell(cell);

                cell = new PdfPCell(new Phrase("Personal Details", FontFactory.GetFont("Times New Roman ,serif", 16, BaseColor.WHITE)));
                cell.Colspan = 5;
                cell.HorizontalAlignment = Element.ALIGN_CENTER;
                cell.BackgroundColor = new BaseColor(129, 211, 201);
                table.AddCell(cell);
                string TypeOfEntry = "";
                string strHead = "";
                for (int j = 0; j < dt.Rows.Count; j++)
                {
                    TypeOfEntry = dt.Rows[j]["TypeOfEntry"].ToString();
                    if (TypeOfEntry != strHead)
                    {
                        cell = new PdfPCell(new Phrase(TypeOfEntry, FontFactory.GetFont("Times New Roman ,serif", 16, BaseColor.WHITE)));
                        cell.Colspan = 5;
                        cell.HorizontalAlignment = Element.ALIGN_CENTER;
                        cell.BackgroundColor = new BaseColor(129, 211, 201);
                        table.AddCell(cell);

                    }
                    strHead = dt.Rows[j]["TypeOfEntry"].ToString();

                    string Label = dt.Rows[j]["Label"].ToString();
                    string Information = dt.Rows[j]["Information"].ToString();
                    cell = new PdfPCell(new Phrase(Label));
                    cell.Colspan = 2;
                    table.AddCell(cell);
                    cell = new PdfPCell(new Phrase(Information));
                    cell.Colspan = 3;
                    table.AddCell(cell);
                }
                pdfDoc.Add(table);

            }
            pdfWriter.CloseStream = false;
            pdfDoc.Close();
            Response.Buffer = true;
            Response.ContentType = "application/pdf";
            Response.AddHeader("content-disposition", "attachment;filename=CaseDetails.pdf");
            Response.Cache.SetCacheability(HttpCacheability.NoCache);
            Response.Write(pdfDoc);
            Response.End();
            return View(model);
        }

