                        System.IO.File.Delete(filenm);
                }
                catch { };

                ClientCustomize cc = new ClientCustomize();
                DataSet ds = new DataSet();

                ds = cc.GetCandidateDetailPendingForPdf(perId);

                PdfWriter.GetInstance(doc, new FileStream(filenm, FileMode.Create));
                doc.Open();
                PdfPTable tableLayout = new PdfPTable(2);
                float[] headers = { 30, 70 };  //Header Widths
                tableLayout.SetWidths(headers);
                tableLayout.HorizontalAlignment = Element.ALIGN_LEFT;
                tableLayout.WidthPercentage = 100;
                tableLayout.HeaderRows = 2;
                tableLayout.AddCell(new PdfPCell(new Phrase("Personal Info", new Font(Font.NORMAL, 13, 1, new iTextSharp.text.BaseColor(153, 51, 0))))
                {
                    Colspan = 2,
                    Border = 0,
                    PaddingBottom = 20,
                    HorizontalAlignment = Element.ALIGN_CENTER
                });
                AddCellToBodyBold(tableLayout, "CompanyRefNo");
                AddCellToBody(tableLayout, Convert.ToString(ds.Tables[0].Rows[0]["CompanyRefNo"]));
                AddCellToBodyBold(tableLayout, "Name");
                AddCellToBody(tableLayout, Convert.ToString(Convert.ToString(ds.Tables[0].Rows[0]["Candidate Name"])));
                AddCellToBodyBold(tableLayout, "FatherName");
                AddCellToBody(tableLayout, Convert.ToString(Convert.ToString(ds.Tables[0].Rows[0]["Father Name"])));
                AddCellToBodyBold(tableLayout, "Gender");
                AddCellToBody(tableLayout, Convert.ToString(Convert.ToString(ds.Tables[0].Rows[0]["Gender"])));
                AddCellToBodyBold(tableLayout, "DOB");
                AddCellToBody(tableLayout, Convert.ToString(Convert.ToString(ds.Tables[0].Rows[0]["DOB"])));

                AddCellToBodyBold(tableLayout, "Mobile No");
                AddCellToBody(tableLayout, Convert.ToString(Convert.ToString(ds.Tables[0].Rows[0]["MobileNo"])));
                doc.Add(tableLayout);
                tableLayout.SpacingBefore = 50f;
                tableLayout.SpacingAfter = 12.5f;

                PdfPTable tableLayout1 = new PdfPTable(2);
                doc.NewPage();
                doc.Add(Add_Candidate_To_PDF_Address(tableLayout1, ds));
                tableLayout1.SpacingBefore = 10f;
                tableLayout1.SpacingAfter = 12.5f;
                PdfPTable tableLayout3 = new PdfPTable(2);
                doc.NewPage();
                doc.Add(Add_Candidate_To_PDF_Education(tableLayout3, ds));
                tableLayout3.SpacingBefore = 10f;
                tableLayout3.SpacingAfter = 12.5f;

                PdfPTable tableLayout2 = new PdfPTable(2);
                doc.NewPage();
                doc.Add(Add_Candidate_To_PDF_Emp(tableLayout2, ds));
                tableLayout2.SpacingBefore = 10f;
                tableLayout2.SpacingAfter = 12.5f;
                doc.Close();

            }
            catch (Exception Ex)
            {
                //ViewBag.ErrorMsg = Ex.Message;
                ViewBag.ErrorMsg = "Invalid paramerter value";
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }

            byte[] fileBytes = null;
            if (System.IO.File.Exists(filenm))
            {
                fileBytes = System.IO.File.ReadAllBytes(filenm);
            }
            if (fileBytes != null)
                return File(fileBytes, MediaTypeNames.Application.Octet, downloadfileNmae);
            else
            {
                return RedirectToAction("GetClientCasesDashBoardInfo", new { CaseStatus = "ReportReceived" });
            }
        }

