        private PdfPTable Add_Content_To_PDF(PdfPTable tableLayout, int pid)
        {

            float[] headers = { 10, 30, 30, 15, 15, 15 };  //Header Widths
            tableLayout.SetWidths(headers);        //Set the pdf headers
            tableLayout.WidthPercentage = 95;       //Set the PDF File witdh percentage


            AddCellToHeader(tableLayout, "Source");
            AddCellToHeader(tableLayout, "Company/University");
            AddCellToHeader(tableLayout, "Company Address/College Name");
            AddCellToHeader(tableLayout, "Designation/Course");
            AddCellToHeader(tableLayout, "Period");
            AddCellToHeader(tableLayout, "Tenure");

            ClientCustomize cc = new ClientCustomize();
            DataSet ds = new DataSet();
            ds = cc.ClientEmpEduDetails(pid);

            foreach (DataRow dr in ds.Tables[0].Rows)
            {
                AddCellToBody(tableLayout, Convert.ToString(dr[0]));
                AddCellToBody(tableLayout, Convert.ToString(dr[1]));
                AddCellToBody(tableLayout, Convert.ToString(dr[2]));
                AddCellToBody(tableLayout, Convert.ToString(dr[3]));
                AddCellToBody(tableLayout, Convert.ToString(dr[4]));
                AddCellToBody(tableLayout, Convert.ToString(dr[5]));
            }
            return tableLayout;
        }

        private static void AddCellToHeader(PdfPTable tableLayout, string cellText)
        {

            tableLayout.AddCell(new PdfPCell(new Phrase(cellText, new Font(Font.FontFamily.HELVETICA, 8, 1, iTextSharp.text.BaseColor.WHITE)))
            { HorizontalAlignment = Element.ALIGN_CENTER, Padding = 5, BackgroundColor = new iTextSharp.text.BaseColor(0, 51, 102) });

        }
        private static void AddCellToBody(PdfPTable tableLayout, string cellText)
        {
            tableLayout.AddCell(new PdfPCell(new Phrase(cellText, new Font(Font.FontFamily.HELVETICA, 8, 1, iTextSharp.text.BaseColor.BLACK)))
            { HorizontalAlignment = Element.ALIGN_CENTER, Padding = 5, BackgroundColor = iTextSharp.text.BaseColor.WHITE });

        }

        private static void AddCellToBodyBold(PdfPTable tableLayout, string cellText)
        {
            tableLayout.AddCell(new PdfPCell(new Phrase(cellText, new Font(Font.FontFamily.HELVETICA, 9, 1, iTextSharp.text.BaseColor.BLACK)))
            { HorizontalAlignment = Element.ALIGN_CENTER, Padding = 5, BackgroundColor = iTextSharp.text.BaseColor.WHITE });

        }






