        [HttpGet]
        [ValidateInput(false)]
        //[ValidateSessionFilter]
        public ActionResult ClientCaseWiseTracker()
        {
            int page = 1;
            string sort = "";
            string sortDir = "asc";
            string fromdate = "";
            string Todate = "";
            string Status = "";
            string processStatus = "";
            ClientDashboardTrackerMISViewModel model = new ClientDashboardTrackerMISViewModel();
            try
            {
                int pageSize = 500;
                int allClients = 1;
                //string CaseStatus = "Insufficiency";
                ClientCustomize cc = new ClientCustomize();

                short ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
                int ClientUserRowID = Convert.ToInt32(Session["ClientUserRowID"]);
                string CreatedBy = Convert.ToString(Session["CreatedBy"]);
                string ClientAccessType = Convert.ToString(Session["ClientAccessType"]);
                //if (ClientAccessType == "3" && ClientRowID > 0)
                //    ClientUserRowID = ClientRowID;
                //ClientUserRowID = Convert.ToInt32(Session["ClientUserRowID"]);

                DataTable dt = cc.GetClientGroup(Convert.ToInt16(Session["ClientRowID"]));
                if (dt.Rows.Count > 0 && ClientRowID == 0)
                {
                    ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
                    allClients = 1;
                }
                if (dt.Rows.Count == 0 && ClientRowID == 0)
                {
                    ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
                }
                model.ClientRowId = ClientRowID;

                if (processStatus == "Export")
                {
                    if (ClientRowID == 277 || model.ClientRowId == 249 || ClientRowID == 410)
                    {
                        //customize mis for sutherland and renault nishan client
                        DataTable dts = new DataTable();
                        if (!string.IsNullOrEmpty(CreatedBy) && CreatedBy == "Client-User")
                        {
                            dts = cc.GetSutherlandClientTracker(ClientRowID, ClientUserRowID, fromdate, Todate, Status);
                        }
                        else
                        {
                            dts = cc.GetSutherlandClientTracker(ClientRowID, 0, fromdate, Todate, Status);
                        }
                        ExportToExcel(dts, "CaseMISTracker");
                    }

                }

                if (model.ClientRowId != 277 && model.ClientRowId != 249 && ClientRowID != 410)
                {
                    if (Status != "")
                    {
                        var data = new List<ClientDashboardTrackerMISViewModel>();
                        if (ClientAccessType == "3")
                        {
                            ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
                            if (Status == "All Open" || Status == "All Closed")
                            {

                                model = repoDashboardClient.getClientCaseWiseAllOpenClosedTracker(page, pageSize, sort.ToLower(), sortDir.ToLower(), ClientRowID, ClientUserRowID, Status, allClients, processStatus);
                            }
                            else
                            {
                                model = repoDashboardClient.GetClientDashBoardTrackerDetail(page, pageSize, sort.ToLower(), sortDir.ToLower(), ClientRowID, ClientUserRowID, fromdate, Todate, allClients, processStatus);

                            }
                        }
                        else
                        {
                            if (!string.IsNullOrEmpty(CreatedBy) && CreatedBy == "Client-User")
                            {
