        [HttpGet]
        public ActionResult showmailhistory(string PersonalRowid = "")
        {
            TempPQPersonalViewModel model = new TempPQPersonalViewModel();

            try
            {
                string Personalrowid = clsCommonMethods.PDecrypt(PersonalRowid);
                ClientCustomize cc = new ClientCustomize();
                DataTable dt = new DataTable();

                List<MailHistortcount> obj = new List<MailHistortcount>();
                dt = cc.mailhistory_data(Convert.ToInt32(Personalrowid));
                if (dt.Rows.Count > 0)
                {
                    foreach (DataRow dr in dt.Rows)
                    {
                        MailHistortcount aa = new MailHistortcount();
                        aa.Sno = dr["S.No."].ToString();
                        aa.ToMail = dr["ToMail"].ToString();
                        aa.SubjectMail = dr["SubjectMail"].ToString();
                        aa.MailObject = dr["MailObject"].ToString();
                        obj.Add(aa);
                    }
                    model.MailHistortcount = obj;

                }
            }
            catch (Exception ex)
            {

            }

            return View(model);

        }

        [ValidateInput(false)]
        public ActionResult UploadCandidateDoc(string CompanyRefNo = "", short SubCheckRowID = 0, string personalrowid = "")
        {
            TempPQCheckdataListViewModel model = new TempPQCheckdataListViewModel();
            try
            {
                string CompanyRefNoDB = (clsCommonMethods.PDecrypt(CompanyRefNo));
                string Personalrowid = (clsCommonMethods.PDecrypt(personalrowid));
                int tempperid = 0;
                ClientCustomize cc = new ClientCustomize();
                DataSet ds = new DataSet();
                DataSet dscase = new DataSet();
                List<TempPQCheckdataViewModel> lmd = new List<TempPQCheckdataViewModel>();
                int ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
                if (ClientRowID == 791 || ClientRowID == 898)
                {
                    DataTable dt1 = cc.GetCaseDocCandidate(CompanyRefNoDB);
                    if (dt1.Rows.Count > 0)
                    {
                        model.caseDocumentName = dt1.Rows[0]["FileName"].ToString();
                        model.caseDocumentPath = "";
                    }
                }
                else
                {
                    DataTable dt1 = cc.GetCaseDocCandidateAll(CompanyRefNoDB);
                    if (dt1.Rows.Count > 0)
                    {
                        model.caseDocumentName = dt1.Rows[0]["FileName"].ToString();
                        model.caseDocumentPath = "";
                    }
