        public async Task<ActionResult> GetAllCadndidateDocInZip(string CompanyRefNo = "", short SubCheckRowID = 0, string personalrowid = "")
        {
            TempPQCheckdataListViewModel model = new TempPQCheckdataListViewModel();
            try
            {
                string CompanyRefNoDB = clsCommonMethods.PDecrypt(CompanyRefNo);
                string Personalrowid = clsCommonMethods.PDecrypt(personalrowid);
                int tempperid = 0;
                ClientCustomize cc = new ClientCustomize();
                List<TempPQCheckdataViewModel> lmd = new List<TempPQCheckdataViewModel>();
                int ClientRowID = Convert.ToInt16(Session["ClientRowID"]);

                // Retrieve both DataTables
                DataTable dt1 = cc.GetCaseDocCandidateAll(CompanyRefNoDB);
                DataTable dt = cc.getCandidateCaseDocumentForLOA(CompanyRefNoDB);

                // Use custom class instead of tuples
                List<FileEntry> filesToZip = new List<FileEntry>();

                // Add files from dt1
                if (dt1.Rows.Count > 0)
                {
                    foreach (DataRow row in dt1.Rows)
                    {
                        string fileName = row["FileName"].ToString();
                        string filePath = "~/Uploads/";
                        if (!string.IsNullOrWhiteSpace(fileName) && !string.IsNullOrWhiteSpace(filePath))
                        {
                            if (filePath.StartsWith("~/"))
                            {
                                filePath = filePath.Replace("~/", @"D:/wwwroot2/");
                            }
                            filesToZip.Add(new FileEntry { FilePath = filePath + fileName, FileName = fileName });
                        }
                    }
                }

                // Add files from dt
                if (dt.Rows.Count > 0)
                {
                    foreach (DataRow row in dt.Rows)
                    {
                        string docName = row["DocumentName"].ToString();
                        string docPath = row["DocumentPath"].ToString();
                        if (!string.IsNullOrWhiteSpace(docName) && !string.IsNullOrWhiteSpace(docPath))
                        {
                            if (docPath.StartsWith("~/"))
                            {
                                docPath = docPath.Replace("~/", @"D:/wwwroot2/");
                            }
                            if (docPath.StartsWith("/"))
                            {
                                docPath = @"D:/wwwroot2/" + docPath.Substring(1);
                            }
                            filesToZip.Add(new FileEntry { FilePath = docPath, FileName = docName });
                        }

                        // For fetching check details
                        if (tempperid == 0)
                        {
                            tempperid = Convert.ToInt32(row["TempPersonalRowID"].ToString());
                        }
                    }
                }

                // Add files from ds (check details)
                if (tempperid > 0)
                {
                    DataSet ds = cc.getTempCheckDetailsInCase(tempperid);
                    if (ds.Tables.Count > 0 && ds.Tables[0].Rows.Count > 0)
                    {
                        foreach (DataRow dr in ds.Tables[0].Rows)
                        {
                            string fileName = dr["FileName"].ToString();
                            string filePath = dr["FilePath"].ToString();

                            if (!string.IsNullOrWhiteSpace(fileName) && !string.IsNullOrWhiteSpace(filePath))
                            {
                                if (filePath.StartsWith("~/"))
                                {
                                    filePath = filePath.Replace("~/", @"D:/wwwroot2/");
                                }
                                if (filePath.StartsWith("/"))
                                {
                                    filePath = @"D:/wwwroot2/" + filePath.Substring(1);
                                }
                                filesToZip.Add(new FileEntry { FilePath = filePath + fileName, FileName = fileName });
                            }

                            // Optional: PAN card file
                            string personalFile = dr["PanCardFileName"].ToString();
                            if (!string.IsNullOrWhiteSpace(personalFile))
                            {
                                string personalPath = dr["FilePath"].ToString();
                                if (personalPath.StartsWith("~/"))
                                {
                                    personalPath = personalPath.Replace("~/", @"D:/wwwroot2/");
                                }
                                if (personalPath.StartsWith("/"))
                                {
                                    personalPath = @"D:/wwwroot2/" + personalPath.Substring(1);
                                }
                                filesToZip.Add(new FileEntry { FilePath = personalPath + personalFile, FileName = personalFile });
                            }
                        }
                    }
                }

                // Create the ZIP archive
                using (var memoryStream = new MemoryStream())
                {

                    using (var zipArchive = new ZipArchive(memoryStream, ZipArchiveMode.Create, true))
                    {
                        foreach (var file in filesToZip)
                        {
                            if (!file.FilePath.Contains("D:\\EMP_Automation\\Attachment\\Mails\\"))
                            {
                                //if (System.IO.File.Exists(Server.MapPath(file.FilePath)))
                                //{
                                //    zipArchive.CreateEntryFromFile(Server.MapPath(file.FilePath), file.FileName);
                                //}

                                string directoryPath = Path.GetDirectoryName(file.FilePath) + Path.DirectorySeparatorChar;
                                string fileName = Path.GetFileName(file.FilePath);
                                var response = await _documentService.GetDocumentAsync(fileName, directoryPath);

                                if (response.IsSuccessStatusCode)
                                {
                                    var fileBytes = await response.Content.ReadAsByteArrayAsync();

                                    // Create entry in ZIP
                                    var zipEntry = zipArchive.CreateEntry(file.FileName, CompressionLevel.Fastest);
                                    using (var entryStream = zipEntry.Open())
                                    {
                                        entryStream.WriteAsync(fileBytes, 0, fileBytes.Length);
                                    }
                                }
                            }

                        }
                    }

                    return File(memoryStream.ToArray(), "application/zip", "CandidateDocuments.zip");
                }
            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = "Error Found !.";
                string ErrorMessage = ViewBag.ErrorMsg ;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
                return RedirectToAction("ExceptionPage", "Home", new { area = "ClientArea", ClientRowId = "", msg = ErrorMessage });
            }
        }

