        [SessionExpireFilterAttributeClient]
        [ValidateInput(false)]
        public async Task<ActionResult> GetCandidatedoc(string FileName)
        {
            string fileName = (clsCommonMethods.PDecrypt(FileName));
            string FldPathDoc = System.Configuration.ConfigurationManager.AppSettings["provideddocuments"].ToString();
            byte[] fileBytes = null;
            var contentType = "";
            HttpResponseMessage response = await _documentService.GetDocumentAsync(fileName);
      

            if (response.IsSuccessStatusCode)
            {
                var jsonString = await response.Content.ReadAsStringAsync();
                var obj = JsonConvert.DeserializeObject<DocumentResponse>(jsonString);

                string docName = obj.DocumentName;
                string base64Data = obj.DocumentValue;


                fileBytes = Convert.FromBase64String(base64Data);
                contentType = System.Web.MimeMapping.GetMimeMapping(docName);
                //fileBytes = await response.Content.ReadAsByteArrayAsync();
                //contentType = response.Content.Headers.ContentType?.ToString() ?? MediaTypeNames.Application.Octet;
                if (fileBytes != null)

                    return File(fileBytes, contentType, docName);
                else
                {
                    return RedirectToAction("GetClientCasesDashBoardInfo", new { CaseStatus = "ReportReceived" });
                }
            }
            return RedirectToAction("GetClientCasesDashBoardInfo", new { CaseStatus = "ReportReceived" });

        }
