        [HttpPost]
        public ActionResult downloadZipFile(FormCollection data)
        {
            string selectedRefNo = data["pim"];
            List<FileInfo> f = new List<FileInfo>();
            string[] refNo = selectedRefNo.Split(',');


            foreach (string file in refNo)
            {
                string FldPathDoc = System.Configuration.ConfigurationManager.AppSettings["CandidateReportdoc"].ToString();
                string fname = Server.MapPath(FldPathDoc) + file + ".pdf";
                FileInfo fi1 = new FileInfo(fname);
                f.Add(fi1);
            }

            using (var memoryStream = new MemoryStream())
            {
                using (var ziparchive = new ZipArchive(memoryStream, ZipArchiveMode.Create, true))
                {
                    foreach (FileInfo fo in f)
                    {
                        try
                        {

                            ziparchive.CreateEntryFromFile(fo.FullName, fo.Name);
                        }
                        catch (Exception Ex)
                        {
                            //ViewBag.ErrorMsg = Ex.Message;
                            ViewBag.ErrorMsg = "Invalid paramerter value";
                            clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
                        }

                    }
                    //return File(memoryStream.ToArray(), "application/zip");
                }

                return File(memoryStream.ToArray(), "application/zip", "BGVReports.zip");
            }



        }

