        [HttpGet]
        [SessionExpireFilterAttributeClient]
        [ValidateInput(false)]
        public ActionResult RefreshDashboardDetails(short objval = 0)
        {
            try
            {
                short ClientRowID = 0;
                int ClientUserRowID = Convert.ToInt32(Session["ClientUserRowID"]);
                ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
                int allClients = 0;
                if (objval == 0)
                    allClients = 1;

                ClientCustomize cc = new ClientCustomize();
                string ClientAccessType = Convert.ToString(Session["ClientAccessType"]);

                if (ClientAccessType == "2" && objval > 0)
                    ClientRowID = objval;

                if (ClientAccessType == "3" && objval > 0)
                    ClientUserRowID = objval;

                string CreatedBy = Convert.ToString(Session["CreatedBy"]);
                ViewBag.ClientDashboard = "Client Dashboard!";

                ViewBag.ClientCasesDashboard = repoDashboardClient.GetClientDashBoardInfo1(ClientRowID, ClientUserRowID, allClients);

                CreateNavigationforInsuffCaseForClient(ClientRowID, ClientUserRowID, objval.ToString(), allClients);
                BindClientListByLogInName(ClientRowID);

                ClientCustomize cn = new ClientCustomize();
                DataTable dt = cn.GetClientTMRights(Convert.ToInt16(Session["ClientUserRowID"]), Convert.ToInt16(Session["ClientRowID"]));
                if (dt.Rows.Count > 0)
                {
                    ViewBag.InterimReportRights = dt.Rows[0]["InterimReportRights"] != DBNull.Value ? dt.Rows[0]["InterimReportRights"].ToString() != null ? Convert.ToBoolean(dt.Rows[0]["InterimReportRights"].ToString()) : false : false;
                    ViewBag.FinalReportRights = dt.Rows[0]["FinalReportRights"] != DBNull.Value ? dt.Rows[0]["FinalReportRights"].ToString() != null ? Convert.ToBoolean(dt.Rows[0]["FinalReportRights"].ToString()) : false : false;
                    ViewBag.WIPStatusRights = dt.Rows[0]["WIPStatusRights"] != DBNull.Value ? dt.Rows[0]["WIPStatusRights"].ToString() != null ? Convert.ToBoolean(dt.Rows[0]["WIPStatusRights"].ToString()) : false : false;
                }
                else
                {
                    ViewBag.InterimReportRights = false;
                    ViewBag.FinalReportRights = false;
                    ViewBag.WIPStatusRights = false;
                }
                //TempData["AcknowledgeStatus"] = 0;
                TempData["ClientRowID"] = Convert.ToInt32(ClientRowID);
                TempData["ClientUserRowID"] = ClientUserRowID;
                DataTable dtk = cc.GetDataRetentionClientAcknowledge(Convert.ToInt32(ClientRowID), ClientUserRowID);
                if (dtk.Rows.Count > 0)
                {
                    if (dtk.Rows[0]["Acknowledge"].ToString() == "Accept")
                    {
                        TempData["AcknowledgeStatus"] = 1;
                    }
                    else
                    {
                        TempData["AcknowledgeStatus"] = 0;
                    }
                }
                else
                {
                    TempData["AcknowledgeStatus"] = 0;
                }
            }
            catch (Exception Ex)
            {

                //ViewBag.ErrorMsg = Ex.Message;
                ViewBag.ErrorMsg = "Invalid paramerter value";
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }
            return PartialView("_DashboardGrouping", new { ClientRowID = objval });
        }
        [HttpPost]
        public JsonResult AcceptAcknowledgment(int clientRowID, int clientUserRowID)
        {
            try
            {

                ClientCustomize cc = new ClientCustomize();
                cc.InsertDataRetentionClientAcknowledge(clientRowID , clientUserRowID);
                DataTable dt = cc.GetDataRetentionClientAcknowledge(clientRowID, clientUserRowID);
                if(dt.Rows.Count > 0)
                {
                    if (dt.Rows[0]["Acknowledge"].ToString() == "Accept")
                    {
                        TempData["AcknowledgeStatus"] = 1;
                    }
                    else
                    {
                        TempData["AcknowledgeStatus"] = 0;
                    }
                }
       

               
                TempData["ClientRowID"] = clientRowID;
                TempData["ClientUserRowID"] = clientUserRowID;

                return Json(new { success = true });
            }
            catch (Exception ex)
            {
              
                return Json(new { success = false, message = ex.Message });
            }
        }
