        [HttpGet]
        [ValidateInput(false)]
        //[ValidateSessionFilter]
        public ActionResult CandidateSearch(int page = 1, string msg = "", string SearchValue = "", string SearchType = "")
        {
            if (clsCommonMethods.PDecrypt(msg) != "")
            {
                ViewBag.ErrorMsg = clsCommonMethods.PDecrypt(msg);
            }
            string sort = "";
            string sortDir = "asc";
            //string SearchType = "";
            short ClientRowID = 0;
            //string SearchValue = "";
            if (page != 1)
            {
                SearchValue = Session["Search"].ToString();
                SearchType = Session["SearchType"].ToString();
            }
            ClientCandidateSearchListPagedModel model = new ClientCandidateSearchListPagedModel();
            try
            {
                if (SearchType == "ActiveStatus" && SearchValue == "")
                {

                    SearchValue = "Active";
                }

                int pageSize = 1000;
                int allClients = 0;
                int ClientUserRowID = 0;


                string ClientAccessType = Convert.ToString(Session["ClientAccessType"]);


                if (ClientAccessType == "3" && ClientRowID > 0)
                {
                    ClientUserRowID = ClientRowID;
                    ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
                    allClients = 0;
                    ViewBag.ClientRowID = ClientRowID;
                }

                if (ClientAccessType == "3" && ClientRowID == 0)
                {
                    ClientUserRowID = Convert.ToInt16(Session["ClientUserRowID"]);
                    ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
                    allClients = 1;
                }

                if (ClientAccessType == "2" && ClientRowID > 0)
                {
                    ClientUserRowID = Convert.ToInt32(Session["ClientUserRowID"]);
                    allClients = 0;
                    ViewBag.ClientRowID = ClientRowID;
                }

                if (ClientAccessType == "2" && ClientRowID == 0)
                {
                    ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
                    ClientUserRowID = Convert.ToInt32(Session["ClientUserRowID"]);
                    allClients = 1;
                }

                if (ClientAccessType == "1")
                {
                    ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
                    ClientUserRowID = Convert.ToInt32(Session["ClientUserRowID"]);
                    allClients = 1;
                }
                string CreatedBy = Convert.ToString(Session["CreatedBy"]);
                model = repoPQPersonal.ClientCandidateSearchList(page, pageSize, sort.ToLower(), sortDir.ToLower(), SearchType, ClientRowID, ClientUserRowID, SearchValue, allClients);

                PQPersonalSearchPagedModel SearchModel = new PQPersonalSearchPagedModel();
                SearchModel.Search = SearchValue;
                model.ItemSearch = SearchModel;
                Session["Search"] = SearchValue;
                Session["SearchType"] = SearchType == "" ? "Candidate Name" : SearchType;
            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = "Error Found !.";
                string ErrorMessage = ViewBag.ErrorMsg ;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
                return RedirectToAction("ExceptionPage", "Home", new { area = "ClientArea", ClientRowId = "", msg = ErrorMessage });
            }
            return View(model);
        }

        [HttpPost]
        [ValidateAntiForgeryToken]
        [ValidateInput(false)]
        //[ValidateSessionFilter]
        public ActionResult CandidateSearch(FormCollection frm)
        {
            int page = 1;
            string sort = "";
            string sortDir = "asc";
            string SearchType = frm["SearchType"];
            short ClientRowID = 0;
            string SearchValue = frm["SearchValue"];
            ViewBag.ErrorMsg = "";
            if (SearchValue != "")
            {
                if (clsCommonMethods.ValidateSQLInjuctionInput(SearchValue) == false)
                {
                    ViewBag.ErrorMsg = "Please Provide Valid input";
                }
            }
            PQPersonalSearchPagedModel SearchModel = new PQPersonalSearchPagedModel();
            ClientCandidateSearchListPagedModel model = new ClientCandidateSearchListPagedModel();
            try
            {
                if (ViewBag.ErrorMsg == "")
                {
                    if (SearchType == "ActiveStatus" && SearchValue == "")
                    {

                        SearchValue = "Active";
                    }

                    int pageSize = 40;
                    int allClients = 0;
                    int ClientUserRowID = 0;
                    if (ClientRowID != 0)
                    {
                        ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
                    }

                    string ClientAccessType = Convert.ToString(Session["ClientAccessType"]);


                    if (ClientAccessType == "3" && ClientRowID > 0)
                    {
                        ClientUserRowID = ClientRowID;
                        ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
                        allClients = 0;
                        ViewBag.ClientRowID = ClientRowID;
                    }

                    if (ClientAccessType == "3" && ClientRowID == 0)
                    {
                        ClientUserRowID = Convert.ToInt16(Session["ClientUserRowID"]);
                        ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
                        allClients = 1;
                    }

                    if (ClientAccessType == "2" && ClientRowID > 0)
                    {
                        ClientUserRowID = Convert.ToInt32(Session["ClientUserRowID"]);
                        allClients = 0;
                        ViewBag.ClientRowID = ClientRowID;
                    }

                    if (ClientAccessType == "2" && ClientRowID == 0)
                    {
                        ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
                        ClientUserRowID = Convert.ToInt32(Session["ClientUserRowID"]);
                        allClients = 1;
                    }

                    if (ClientAccessType == "1")
                    {
                        ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
                        ClientUserRowID = Convert.ToInt32(Session["ClientUserRowID"]);
                        allClients = 1;
                    }
                    string CreatedBy = Convert.ToString(Session["CreatedBy"]);
                    model = repoPQPersonal.ClientCandidateSearchList(page, pageSize, sort.ToLower(), sortDir.ToLower(), SearchType, ClientRowID, ClientUserRowID, SearchValue, allClients);

                }

                SearchModel.Search = SearchValue;
                model.ItemSearch = SearchModel;
                Session["Search"] = SearchValue;
                Session["SearchType"] = SearchType;
            }
            catch (Exception Ex)
            {
                SearchModel.Search = SearchValue;
                model.ItemSearch = SearchModel;
                Session["Search"] = SearchValue;
                Session["SearchType"] = SearchType;
                ViewBag.ErrorMsg = "Error Found !.";
                string ErrorMessage = ViewBag.ErrorMsg ;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
                return RedirectToAction("ExceptionPage", "Home", new { area = "ClientArea", ClientRowId = "", msg = ErrorMessage });
            }
            return RedirectToAction("CandidateSearch", new { msg = clsCommonMethods.PEncrypt(ViewBag.ErrorMsg), SearchValue = SearchValue, SearchType = SearchType });
        }

