        //[HttpPost]
        public JsonResult GetCandidatesByName(string candidateName, int clientRowID)
        {
            if (string.IsNullOrWhiteSpace(candidateName))
            {
                return Json(Enumerable.Empty<Candidatelist>(), JsonRequestBehavior.AllowGet);
            }

            try
            {
                var cc = new ClientCustomize();
                var candidates = cc.GetCandidatesByName(candidateName, clientRowID);

                if (candidates.Tables.Count > 0 && candidates.Tables[0].Rows.Count > 0)
                {
                    var candidateList = candidates.Tables[0].Rows.Cast<DataRow>().Select(row => new Candidatelist
                    {
                        CandidateFullName = row["CandidateFullName"].ToString()
                    }).ToList();

                    //ViewBag.CandidateList = new SelectList(candidateList, "candidateLists", "StateName");
                    return Json(candidateList, JsonRequestBehavior.AllowGet);
                }
                else
                {
                    return Json(new { error = "No candidates found" }, JsonRequestBehavior.AllowGet);
                }
            }
            catch (Exception ex)
            {
                // Log the error
                return Json(Enumerable.Empty<Candidatelist>(), JsonRequestBehavior.AllowGet);
            }
        }



