        [HttpPost]
        [ValidateAntiForgeryToken]
        [ValidateInput(false)]
        // [ValidateSessionFilter]
        public ActionResult DuplicateReference(FormCollection form, string submitButton = "")
        {
            string TicketNo = form["TicketNo"];
            ClientCandidateSearchListPagedModel model = new ClientCandidateSearchListPagedModel();
            try
            {

                short ClientRowId = Convert.ToInt16(Session["ClientRowID"]);
                if (Request.QueryString["ticid"] != null)
                {
                    TicketNo = Request.QueryString["ticid"].ToString();
                    int page = 1;
                    int pageSize = 20;
                    model = repoPQPersonal.GetDuplicateReferenceDetails(page, pageSize, "", "asc", ClientRowId, 0, TicketNo, "", "");
                }
                if (submitButton == "Search")
                {
                    int page = 1;
                    int pageSize = 20;
                    model = repoPQPersonal.GetDuplicateReferenceDetails(page, pageSize, "", "asc", ClientRowId, 0, TicketNo, "", "");
                    ViewBag.TicketId = TicketNo;
                }
                else if (submitButton == "Export to Excel")
                {
                    int page = 1;
                    int pageSize = 20;
                    model = repoPQPersonal.GetDuplicateReferenceDetails(page, pageSize, "", "asc", ClientRowId, 0, TicketNo, "", "");
                    ExportCandidateDuplicateSearch(TicketNo);
                }

                GetDupliacteTicket(model, ClientRowId);
            }
            catch (Exception Ex)
            {
                //ViewBag.ErrorMsg = Ex.Message;
                ViewBag.ErrorMsg = "Invalid paramerter value";
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }
            return View(model);

        }

