        [HttpPost]
        [ValidateAntiForgeryToken]
        [ValidateInput(false)]
        public async Task<ActionResult> CaseBulkDownload(FormCollection data, string SearchValue)
        {
            short ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
            int allClients = 0;
            ClientCustomize cc = new ClientCustomize();
            int ClientUserRowID = 0;
            string ClientAccessType = Convert.ToString(Session["ClientAccessType"]);


            if (ClientAccessType == "3" && ClientRowID > 0)
            {
                string dbvalue = SearchValue.Replace("\r\n", ",");
                string[] kk = dbvalue.Split(',');
                int LoginUserId = Convert.ToInt32(Session["ClientUserRowID"]);
                foreach (string s in kk)
                {
                    if (s != "")
                    {
                        //int k = cc.checkReportsAccess(s, ClientUserRowID);
                        int k = cc.checkReportsAccessClient(s, ClientUserRowID, LoginUserId, ClientAccessType);
                        if (k == 0)
                        {
                            TempData["SuccessMsg"] = "cases are not belongs to you, please contact to the administrator !";
                            return View();
                        }
                    }
                }
                ClientUserRowID = 0;
                ClientUserRowID = ClientRowID;
                ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
                allClients = 0;
                ViewBag.ClientRowID = ClientRowID;
            }

            if (ClientAccessType == "3" && ClientRowID == 0)
            {
                ClientUserRowID = Convert.ToInt16(Session["ClientUserRowID"]);
                ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
                allClients = 1;
            }

            if (ClientAccessType == "2" && ClientRowID > 0)
            {
                ClientUserRowID = Convert.ToInt32(Session["ClientUserRowID"]);
                allClients = 0;
                ViewBag.ClientRowID = ClientRowID;
            }

            if (ClientAccessType == "2" && ClientRowID == 0)
            {
                ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
                ClientUserRowID = Convert.ToInt32(Session["ClientUserRowID"]);
                allClients = 1;
            }

            if (ClientAccessType == "1")
            {
                ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
                ClientUserRowID = Convert.ToInt32(Session["ClientUserRowID"]);
                allClients = 1;
            }
            List<ClientBulkDownlode> f = new List<ClientBulkDownlode>();
            string[] refNo = SearchValue.Split(new string[] { "\r\n" }, StringSplitOptions.None);
            string CaseStatus = "BulkDownload";
            if (refNo.Length > 25 && ClientRowID != 1638)
            {
                TempData["SuccessMsg"] = "more than 25 cases are not allowed to downloded at a time !";
            }
            else
            {
                string dbvalue = SearchValue.Replace("\r\n", ",");
                string[] kk = dbvalue.Split(',');
                string CandidateFullName = "";
                string PortalName = "";
                foreach (string s in kk)
                {
                    string reportFileName = s + ".pdf";
                    DataTable ddd = cc.getAutoExistCompRefNoNew(s);
                    if (ddd.Rows.Count > 0)
                    {
                        if (Convert.ToInt32(ddd.Rows[0]["CaseStatus"]) == 5)
                        {
                            continue;
                        }
                        if (ddd.Rows[0]["CandidateFullName"].ToString() != "")
                        {
                            reportFileName = ddd.Rows[0]["ReportFileName"].ToString();
                            CandidateFullName = ddd.Rows[0]["CandidateFullName"].ToString();
                            PortalName = ddd.Rows[0]["PortalName"].ToString();
                        }
                    }
                    ClientBulkDownlode tt = new ClientBulkDownlode();
                    string fileName = s;
                    string CompanyRefNo = s;
                    tt.CompanyRefno = CompanyRefNo;
                    if (!string.IsNullOrEmpty(CompanyRefNo))
                    {
                        string FldPathDoc = "";
                        string fname = "";
                        if (PortalName == "New Portal")
                        {
                            FldPathDoc = System.Configuration.ConfigurationManager.AppSettings["CandidateReportdoc"].ToString();
                            if (FldPathDoc.StartsWith("~/"))
                            {
                                FldPathDoc = FldPathDoc.Replace("~/", @"D:/wwwroot2/");
                            }
                            if (FldPathDoc.StartsWith("/"))
                            {
                                FldPathDoc = @"D:/wwwroot2/" + FldPathDoc.Substring(1);
                            }
                            fname = FldPathDoc + reportFileName;
                            //fname = Server.MapPath(FldPathDoc) + reportFileName;
                        }
                        else
                        {
                            //FldPathDoc = System.Configuration.ConfigurationManager.AppSettings["CandidateReportdoc_Old"].ToString();
                            fname = "F:/wwwroot/Documents/CandidateReport/" + reportFileName;
                        }

                        FileInfo fi1 = new FileInfo(fname);
                        tt.fileDetails = fi1;
                        if (PortalName == "New Portal")
                        {
                            tt.FileDownloadName = repoDashboardClient.downloadReportFileName(s) + ".pdf";
                        }
                        else
                        {
                            tt.FileDownloadName = reportFileName;
                        }
                        f.Add(tt);
                    }
                }

                using (var memoryStream = new MemoryStream())
                {
                    using (var ziparchive = new ZipArchive(memoryStream, ZipArchiveMode.Create, true))
                    {
                        foreach (ClientBulkDownlode fo in f)
                        {
                            try
                            {
                                if (ClientRowID == 683)
                                {
                                    string fileName = Path.GetFileNameWithoutExtension(fo.FileDownloadName);
                                    DataTable reportSecurity = cc.ReportSeurityBYdatabase(ClientRowID, fo.CompanyRefno);
                                    string pwd = "";
                                    if (reportSecurity.Rows.Count > 0)
                                    {
                                        pwd = reportSecurity.Rows[0]["Reportvalidation"].ToString();
                                    }

                                    HttpResponseMessage response = await _documentService.GetDocumentAsync(Path.GetFileName(fo.fileDetails.FullName), Path.GetDirectoryName(fo.fileDetails.FullName) + Path.DirectorySeparatorChar);

                                    if (response.IsSuccessStatusCode)
                                    {
                                        var jsonString = await response.Content.ReadAsStringAsync();
                                        var obj = JsonConvert.DeserializeObject<DocumentResponse>(jsonString);

                                        string docName = obj.DocumentName;
                                        string base64Data = obj.DocumentValue;

                                        byte[] fileBytes = Convert.FromBase64String(base64Data);
                                        string contentType = System.Web.MimeMapping.GetMimeMapping(docName);
                                        byte[] encryptedData = null;
                                        using (MemoryStream input = new MemoryStream(fileBytes))
                                        using (MemoryStream output = new MemoryStream())
                                        {
                                            PdfReader reader = new PdfReader(input);
                                            PdfEncryptor.Encrypt(reader, output, true, pwd, pwd, PdfWriter.ALLOW_SCREENREADERS);
                                            encryptedData = output.ToArray();
                                        }
                                        var zipEntry = ziparchive.CreateEntry(fo.FileDownloadName);
                                        using (var zipStream = zipEntry.Open())
                                        {
                                            zipStream.Write(encryptedData, 0, encryptedData.Length);
                                        }
                                    }
                                    //byte[] fileBytes = System.IO.File.ReadAllBytes(fo.fileDetails.FullName);
                                    //byte[] encryptedData = null;
                                    //using (MemoryStream input = new MemoryStream(fileBytes))
                                    //using (MemoryStream output = new MemoryStream())
                                    //{
                                    //    PdfReader reader = new PdfReader(input);
                                    //    PdfEncryptor.Encrypt(reader, output, true, pwd, pwd, PdfWriter.ALLOW_SCREENREADERS);
                                    //    encryptedData = output.ToArray();
                                    //}
                                    //var zipEntry = ziparchive.CreateEntry(fo.FileDownloadName);
                                    //using (var zipStream = zipEntry.Open())
                                    //{
                                    //    zipStream.Write(encryptedData, 0, encryptedData.Length);
                                    //}
                                }

                                else
                                {
                                    HttpResponseMessage response = await _documentService.GetDocumentAsync(Path.GetFileName(fo.fileDetails.FullName), Path.GetDirectoryName(fo.fileDetails.FullName) + Path.DirectorySeparatorChar);

                                    if (response.IsSuccessStatusCode)
                                    {
                                        var jsonString = await response.Content.ReadAsStringAsync();
                                        var obj = JsonConvert.DeserializeObject<DocumentResponse>(jsonString);

                                        string docName = obj.DocumentName;
                                        string base64Data = obj.DocumentValue;


                                        byte[] fileBytes = Convert.FromBase64String(base64Data);
                                        string contentType = System.Web.MimeMapping.GetMimeMapping(docName);
                                        ZipArchiveEntry entry = ziparchive.CreateEntry(fo.FileDownloadName); ;
                                        using (var entryStream = entry.Open())
                                        {
                                            entryStream.Write(fileBytes, 0, fileBytes.Length);
                                        }
                                    }
                                    //ziparchive.CreateEntryFromFile(fo.fileDetails.FullName, fo.FileDownloadName);
                                }
                            }
                            catch (Exception Ex)
                            {
                                //ViewBag.ErrorMsg = Ex.Message;
                                ViewBag.ErrorMsg = "Invalid paramerter value";
                                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
                            }

                        }
                        //return File(memoryStream.ToArray(), "application/zip");
                    }

                    return File(memoryStream.ToArray(), "application/zip", "BGVReports.zip");
                }
            }
            return View();
        }

        [HttpPost]
        [ValidateAntiForgeryToken]
        [ValidateInput(false)]
        public async Task<ActionResult> BulkLOADownload(FormCollection data, string SearchValue)
        {
          
            short SessionClientRowID = Convert.ToInt16(Session["ClientRowID"]);
            if (SessionClientRowID != 1071)
            {
                TempData["SuccessMsg"] = "Bulk LOA Download is not available for this client !";
                ModelState.Remove("SearchValue");
                return View("CaseBulkDownload");
            }

            
            short ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
            int allClients = 0;
            ClientCustomize cc = new ClientCustomize();
            int ClientUserRowID = 0;
            string ClientAccessType = Convert.ToString(Session["ClientAccessType"]);

            if (ClientAccessType == "3" && ClientRowID > 0)
            {
                string dbvalue = SearchValue.Replace("\r\n", ",");
                string[] kk = dbvalue.Split(',');
                int LoginUserId = Convert.ToInt32(Session["ClientUserRowID"]);
                foreach (string s in kk)
                {
                    if (s != "")
                    {
                        int k = cc.checkReportsAccessClient(s, ClientUserRowID, LoginUserId, ClientAccessType);
                        if (k == 0)
                        {
                            TempData["SuccessMsg"] = "cases are not belongs to you, please contact to the administrator !";
                            ModelState.Remove("SearchValue");
                            return View("CaseBulkDownload");
                        }
                    }
                }
                ClientUserRowID = 0;
                ClientUserRowID = ClientRowID;
                ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
                allClients = 0;
                ViewBag.ClientRowID = ClientRowID;
            }

            if (ClientAccessType == "3" && ClientRowID == 0)
            {
                ClientUserRowID = Convert.ToInt16(Session["ClientUserRowID"]);
                ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
                allClients = 1;
            }

            if (ClientAccessType == "2" && ClientRowID > 0)
            {
                ClientUserRowID = Convert.ToInt32(Session["ClientUserRowID"]);
                allClients = 0;
                ViewBag.ClientRowID = ClientRowID;
            }

            if (ClientAccessType == "2" && ClientRowID == 0)
            {
                ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
                ClientUserRowID = Convert.ToInt32(Session["ClientUserRowID"]);
                allClients = 1;
            }

            if (ClientAccessType == "1")
            {
                ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
                ClientUserRowID = Convert.ToInt32(Session["ClientUserRowID"]);
                allClients = 1;
            }

            string[] refNo = SearchValue.Split(new string[] { "\r\n" }, StringSplitOptions.None);
            if (refNo.Length > 25 && ClientRowID != 1638)
            {
                TempData["SuccessMsg"] = "more than 25 LOA are not allowed to be downloaded at a time !";
                ModelState.Remove("SearchValue");
                return View("CaseBulkDownload");
            }

            string dbvalueLoa = SearchValue.Replace("\r\n", ",");
            string[] refnos = dbvalueLoa.Split(',');

            using (var memoryStream = new MemoryStream())
            {
                using (var ziparchive = new ZipArchive(memoryStream, ZipArchiveMode.Create, true))
                {
                    foreach (string s in refnos)
                    {
                        if (string.IsNullOrWhiteSpace(s)) continue;

                        try
                        {
                            DataTable loaRow = cc.GetLatestLOAByCompanyRefNo(s);
                            if (loaRow.Rows.Count == 0)
                            {
                                continue;
                            }

                            string fileName = loaRow.Rows[0]["FileName"].ToString();
                            string filePath = loaRow.Rows[0]["FilePath"].ToString();

                            
                            if (filePath.StartsWith("~/"))
                            {
                                filePath = filePath.Replace("~/", @"D:/wwwroot2/");
                            }
                            if (filePath.StartsWith("/"))
                            {
                                filePath = @"D:/wwwroot2/" + filePath.Substring(1);
                            }

                            HttpResponseMessage response = await _documentService.GetDocumentAsync(fileName, filePath);
                            if (response.IsSuccessStatusCode)
                            {
                                var jsonString = await response.Content.ReadAsStringAsync();
                                var obj = JsonConvert.DeserializeObject<DocumentResponse>(jsonString);

                                string docName = obj.DocumentName;
                                string base64Data = obj.DocumentValue;
                                byte[] fileBytes = Convert.FromBase64String(base64Data);

                                string extension = Path.GetExtension(fileName);
                                string zipEntryName = s + extension; // rename by ref no, e.g. ABC123.docx

                                ZipArchiveEntry entry = ziparchive.CreateEntry(zipEntryName);
                                using (var entryStream = entry.Open())
                                {
                                    entryStream.Write(fileBytes, 0, fileBytes.Length);
                                }
                            }
                        }
                        catch (Exception Ex)
                        {
                            ViewBag.ErrorMsg = "Invalid paramerter value";
                            clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
                        }
                    }
                }

                return File(memoryStream.ToArray(), "application/zip", "BGVLOA.zip");
            }
        }

