        [NonAction]
        private void CreateMenuitemforDataEntryOperator(int id = 0, int CheckStatusId = 0)
        {
            try
            {
                if (id > 0)
                {
                    var CandidateChecks = repoPQCandidateCheck.GetInfuffCheck(id);
                    //string NavInputDataMenuList = "<li><a href='" + Url.Action("UpdateCandidateDetails", "ProvidedInfo", new { id = id }) + "' > Personal Info </a></li>";
                    string NavInputDataMenuList = "";
                    if (CandidateChecks != null && CandidateChecks.Count() > 0)
                    {
                        string pageName = "";
                        ClientCustomize cc = new ClientCustomize();
                        foreach (var item in CandidateChecks)
                        {
                            if (item.ClientPackageRowID > 0)
                            {
                                var chkData = repoClientPackage.GetPackageDetailsById(item.ClientPackageRowID);
                                DataTable dt = cc.GetCheckIdentifyId(item.PersonalRowID, chkData.SubCheckRowID, chkData.CheckFamilyRowID);

                                pageName = GetPageNameByCheckIdNew(item.ClientRowID, item.PersonalRowID, chkData.CheckFamilyRowID, chkData.SubCheckRowID);
                                if (!string.IsNullOrEmpty(pageName))
                                {
                                    int identy = 0;
                                    if (dt.Rows.Count > 0)
                                    {
                                        identy = Convert.ToInt32(dt.Rows[0]["id"].ToString());

                                    }
                                    pageName = "InsufficiencyCheckClearByClient";

                                    string urlValue = Url.Content("~/ClientArea/ClientInsuff/" + pageName + "?id=" + identy + "&ClientRowId=" + clsCommonMethods.PEncrypt(item.ClientRowID.ToString()) + "&ChFamilRowId=" + chkData.CheckFamilyRowID + "&subCheckId=" + chkData.SubCheckRowID
   + "&PersonalRowID=" + item.PersonalRowID + "&CompanyRefNo=" + item.compantRefNo);

                                    NavInputDataMenuList += "<li><a href='" + urlValue + "'> " + chkData.SubCheckFamillyName + " </a></li>";
                                }
                            }
                            else if (item.ClientCheckRowID > 0)
                            {

                                var chkData = repoClientCheck.GetChecksDetailsById(item.ClientCheckRowID);
                                DataTable dt = cc.GetCheckIdentifyId(item.PersonalRowID, chkData.SubCheckRowID, chkData.CheckFamilyRowID);
                                pageName = GetPageNameByCheckIdNew(item.ClientRowID, item.PersonalRowID, chkData.CheckFamilyRowID, chkData.SubCheckRowID);
                                if (!string.IsNullOrEmpty(pageName))
                                {
                                    int identy = 0;
                                    if (dt.Rows.Count > 0)
                                    {
                                        identy = Convert.ToInt32(dt.Rows[0]["id"].ToString());

                                    }
                                    pageName = "InsufficiencyCheckClearByClient";
                                    string urlValue = Url.Content("~/ClientArea/ClientInsuff/" + pageName + "?id=" + identy + "&ClientRowId=" + clsCommonMethods.PEncrypt(item.ClientRowID.ToString()) + "&ChFamilRowId=" + chkData.CheckFamilyRowID + "&subCheckId=" + chkData.SubCheckRowID
                                       + "&PersonalRowID=" + item.PersonalRowID + "&CompanyRefNo=" + item.compantRefNo);
                                    NavInputDataMenuList += "<li><a href='" + urlValue + "'> " + chkData.SubCheckFamillyName + " </a></li>";

                                }
                            }
                        }
                    }
                    Session["NavInputDataMenuList"] = NavInputDataMenuList;
                }
            }
            catch (Exception)
            {

                throw;
            }
        }

        [NonAction]
        private string GetPageNameByCheckIdNew(short ClientRowId = 0, int PersonalRowID = 0, short ChFamilRowId = 0, short subCheckId = 0)
        {
            try
            {
                string pageName = string.Empty;
                bool isStatusExists;
                ClientCustomize cc = new ClientCustomize();
                int retVal = cc.checkExistsInGivenStatus(PersonalRowID, subCheckId, "11,22");
                if (retVal == 1)
                    isStatusExists = true;
                else
                    isStatusExists = false;

                if (ChFamilRowId == 2 && isStatusExists)
                {
                    pageName = "AddAddressInfo";
                }
                if (ChFamilRowId == 12 && isStatusExists)
                {
                    pageName = "AddEmploymentInfo";
                }
                if (ChFamilRowId == 11 && isStatusExists)
                {
                    pageName = "AddEducationInfo";
                }
                if (ChFamilRowId == 26 && isStatusExists)
                {
                    pageName = "AddNationalIdentityInfo";
                }
                if (ChFamilRowId == 30 && isStatusExists)
                {
                    pageName = "AddReferenceInfo";
                }
                if (ChFamilRowId == 5 && isStatusExists)
                {
                    pageName = "AddCriminalInfo";
                }
                if (ChFamilRowId == 40 && isStatusExists)
                {
                    pageName = "AddSpecialCheckInfo";
                }
                return pageName;
            }
            catch (Exception)
            {

                throw;
            }
        }

        [HttpGet]
