                    model.CriminalProvidedList = CRIProvidedList;

                }

                #endregion
            }
            catch (Exception Ex)
            {
                // ViewBag.ErrorMsg = Ex.Message;
                ViewBag.ErrorMsg = "Invalid paramerter value";
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }
            Session["Type"] = "";
            return View(model);
        }

