        [HttpPost]
        public ActionResult RejectCandidatedetailsCheckWise(FormCollection frm, string[] checkname, string PersonalRowID = "", string ClientID = "", string Remarks = "")
        {
            ClientCustomize cc = new ClientCustomize();
