                    {
                        string spocEmail = "";
                        string cSpocEmail = "";
                        string mobileno = "";

                        string TrmFldPathDoc = "";
                        string fileName = "";

                        string MailSignature = string.Empty;
                        string From = string.Empty;
                        string DisplayName = string.Empty;
                        string Cc = "";

