        [ValidateInput(false)]
        public ActionResult AddCheck(HttpPostedFileBase file, string Search = "", int pageNo = 1, int pageSize = 100, string SaveWork = "")
        {
            try
            {
                if (pageNo < 0)
                {
                    pageNo = 1;
                }
                if (Search == "")
                {
                    BindSubcheckname(0, 0, "New");
                }

                int ClientRowID = 0;
                string DatabaseName = "New";
                int ID = Convert.ToInt32(Session["ClientRowID"]);
                ViewBag.ClientId = ID;
                ClientServiceListViewModel model = new ClientServiceListViewModel();

                // ClientDashboardCheckSummaryDetailViewModel model = new ClientDashboardCheckSummaryDetailViewModel();
                DataTable dt = new DataTable();
                ClientCustomize cc = new ClientCustomize();
                dt = cc.GetCandidateChecks(Search);

                List<ClientDashboardCheckSummaryDetailViewModel> lmd = new List<ClientDashboardCheckSummaryDetailViewModel>();
                if (dt.Rows.Count > 0)
                {
                    foreach (DataRow dr in dt.Rows) // loop for adding add from dataset to list<modeldata>
                    {
                        lmd.Add(new ClientDashboardCheckSummaryDetailViewModel
                        {
                            SecuritasID = (dr["CompanyRefNo"].ToString()),
                            CheckName = (dr["SubCheckName"].ToString()),
                            CheckStatus = dr["CheckStatus"].ToString(),
                            CheckStatusID = (dr["CheckStatusID"].ToString()),
                            OrderDate = (dr["orderDate"].ToString()),
                            OutDate = (dr["outDate"].ToString()),
                            CreatedDate = (dr["CreationDate"].ToString()),
                            ColorName = dr["ColorName"].ToString(),
                            ClientCheckRowID = Convert.ToInt32(dr["ClientCheckRowID"]),
                            Name = (dr["Name"].ToString()),

                        });
                        DatabaseName = dr["DatabaseName"].ToString();

                    }
                    ClientRowID = Convert.ToInt32(dt.Rows[0]["ClientRowID"]);
                    model.TotalRecords = dt.Rows.Count;
                    BindSubcheckname(Convert.ToInt32(dt.Rows[0]["ClientRowID"]), Convert.ToInt32(dt.Rows[0]["PersonalRowID"]), DatabaseName);

                }
                else
                {
                    model.TotalRecords = 0;
                }
                model.PageSize = pageSize;
                model.ClientServiceChecks = lmd.Skip((pageNo - 1) * pageSize).Take(pageSize);

                if ((SaveWork != "" && SaveWork == "Add") && (Request.Form["ddlColor"].ToString() != "0") && (dt.Rows[0]["PersonalRowID"].ToString() != ""))
                {
                    DataTable dtcheck = new DataTable();
                    if (ClientRowID == 679)
                    {
                        if (file == null)
                        {
                            TempData["SuccessMsg"] = "Please attach file";
                            return RedirectToAction("AddCheck", "Home", new { Search = Search });
                        }
                        dtcheck = cc.CheckCasestatus_679(Convert.ToInt32(dt.Rows[0]["PersonalRowID"]), DatabaseName);
                    }
                    else
                    {
                        dtcheck = cc.CheckCasestatus(Convert.ToInt32(dt.Rows[0]["PersonalRowID"]));
                    }

                    if (dtcheck.Rows.Count > 0)
                    {
                        int strDDLValue = Convert.ToInt32(Request.Form["ddlColor"]);

                        if (ClientRowID == 679)
                        {

                            cc.PQCandidateChecksAddCheck_679(Convert.ToInt32(dt.Rows[0]["PersonalRowID"]), Convert.ToInt32(dt.Rows[0]["ClientRowID"]), Convert.ToInt32(Request.Form["ddlColor"]), DatabaseName);

                            if (file != null)
                            {
                                DataTable dataTable = new DataTable();
                                dataTable = cc.GetSubCheckID(Convert.ToInt32(Request.Form["ddlColor"]));
                                List<ClientDashboardCheckSummaryDetailViewModel> cdcmodel = new List<ClientDashboardCheckSummaryDetailViewModel>();
                                if (dataTable.Rows.Count > 0)
                                {
                                    foreach (DataRow dr in dataTable.Rows)
                                    {
                                        cdcmodel.Add(new ClientDashboardCheckSummaryDetailViewModel
                                        {
                                            SubCheckRowID = Convert.ToInt32(dr["SubCheckRowID"])
                                        });
                                    }
                                }
                                var FileNameOnly = Path.GetFileNameWithoutExtension(file.FileName);
                                var Ext = Path.GetExtension(file.FileName);
                                string CompleteFile = (Convert.ToInt32(dt.Rows[0]["PersonalRowID"]) + "_" + Convert.ToInt32(dataTable.Rows[0]["SubCheckRowID"]) + "_" + DateTime.Now.ToString("ddMMyyyyHHmmss") + "_" + FileNameOnly).Replace("'", "_").Replace(" ", "_").Replace("-", "_") + Ext;
                                string FileName = CompleteFile;
                                model.caseDocumentPath = Url.Content(Path.Combine("~/Documents/CandidateDocuments/ProvidedDocuments", FileName));
                                cc.InsertAddCheckDocs(Convert.ToInt32(dt.Rows[0]["PersonalRowID"]), Convert.ToInt32(dataTable.Rows[0]["SubCheckRowID"]), "Add check Document", 1, "Verified", "Add Check", FileName, model.caseDocumentPath, 0, 0, "", 0, 0, DateTime.Now, 0, "", 0, "");
                                if (file.ContentLength > 0)
                                {

                                    string _path = Path.Combine(Server.MapPath("~/Documents/CandidateDocuments/ProvidedDocuments"), FileName);
                                    file.SaveAs(_path);
                                }
                            }
                        }
                        else
                        {
                            cc.PQCandidateChecksAddCheck(Convert.ToInt32(dt.Rows[0]["PersonalRowID"]), Convert.ToInt32(dt.Rows[0]["ClientRowID"]), Convert.ToInt32(Request.Form["ddlColor"]));
                        }

                        TempData["SuccessMsg"] = "Record Added Successfully!";
                        return RedirectToAction("AddCheck", "Home", new { Search = Search });
                    }
                    else
                    {

                        TempData["SuccessMsg"] = "You can not add check on Initiation stage";
                    }
                }
                else
                {
                    if (SaveWork == "Add")
                    {

                        TempData["SuccessMsg"] = "Please fill detail";
                    }

                }


                return View(model);



            }
            catch (Exception)
            {
                throw;
            }

        }
