        public ActionResult ExportPDF(string PersonalRowID)
        {
            PersonalRowID = clsCommonMethods.PDecrypt(PersonalRowID);
            ClientCustomize cc = new ClientCustomize();
            DataTable dt = new DataTable();
            if (PersonalRowID != "")
            {
                dt = cc.GetExportLoa(Convert.ToInt32(PersonalRowID));
            }
            if (dt.Rows.Count > 0)
            {
                ViewBag.LOA_Signature = dt.Rows[0]["LOA_Signature"].ToString();
                if (Convert.ToString(dt.Rows[0]["LOA_Signature"]) != "")
                {
                    string CanLOASignature = dt.Rows[0]["LOA_Signature"].ToString();
                    ViewBag.LoaImage = LoadImage(CanLOASignature);
                    ViewBag.LoaImageB64 = CanLOASignature;

                }
                else
                {
                    ViewBag.CanLOASignature = "";
                }
                ViewBag.LOA_Name = dt.Rows[0]["LOA_Name"].ToString();
                ViewBag.CreatedDate = dt.Rows[0]["CreatedDate"].ToString();
            }
            return View();
        }


        public Image LoadImage(string Base64Image)
        {
            byte[] bytes = Convert.FromBase64String(Base64Image);

            Image image;
            using (MemoryStream ms = new MemoryStream(bytes))
            {
                image = Image.FromStream(ms);
            }

            return image;
        }

