        public async Task<ActionResult> GetCaseDocNew(string ImageName, string ImagePath)
        {

            string FldPathDoc = System.Configuration.ConfigurationManager.AppSettings["ClientUploadedDocuments"].ToString();
            string provideddocuments = System.Configuration.ConfigurationManager.AppSettings["ClientUploadedDocuments_New"].ToString();
            string provideddocuments1 = System.Configuration.ConfigurationManager.AppSettings["provideddocuments"].ToString();
            string contentType = "";
            //string filePath = Server.MapPath("~" + ImagePath);

                byte[] fileBytes = null;

           
                if (ImagePath.StartsWith("~/"))
                {
                    ImagePath = ImagePath.Replace("~/", @"D:/wwwroot2/");
                }
                if (ImagePath.StartsWith("/"))
                {
                    ImagePath = @"D:/wwwroot2/" + ImagePath.Substring(1);
                }
                string directoryPath = Path.GetDirectoryName(ImagePath) + Path.DirectorySeparatorChar;
                string fileName = Path.GetFileName(ImagePath);
                HttpResponseMessage response = await _documentService.GetDocumentAsync(fileName , directoryPath);
                if (response.IsSuccessStatusCode)
                {
                    var jsonString = await response.Content.ReadAsStringAsync();
                    var obj = JsonConvert.DeserializeObject<DocumentResponse>(jsonString);

                    string docName = obj.DocumentName;
                    string base64Data = obj.DocumentValue;


                    fileBytes = Convert.FromBase64String(base64Data);
                    contentType = System.Web.MimeMapping.GetMimeMapping(docName);
                }
                else
                {
                    if (provideddocuments1.StartsWith("~/"))
                    {
                        provideddocuments1 = provideddocuments1.Replace("~/", @"D:/wwwroot2/");
                    }
                    if (provideddocuments1.StartsWith("/"))
                    {
                        provideddocuments1 = @"D:/wwwroot2/" + provideddocuments1.Substring(1);
                    }
                      directoryPath = provideddocuments1;
                      fileName = ImageName;
                      response = await _documentService.GetDocumentAsync(fileName, directoryPath);
                    if (response.IsSuccessStatusCode)
                    {
                        var jsonString = await response.Content.ReadAsStringAsync();
                        var obj = JsonConvert.DeserializeObject<DocumentResponse>(jsonString);

                        string docName = obj.DocumentName;
                        string base64Data = obj.DocumentValue;


                        fileBytes = Convert.FromBase64String(base64Data);
                        contentType = System.Web.MimeMapping.GetMimeMapping(docName);
                    }
                }

            

            if (Convert.ToInt16(Session["ClientRowID"]) == 791 || Convert.ToInt16(Session["ClientRowID"]) == 898)
            {
                string provideddocumentsCand = System.Configuration.ConfigurationManager.AppSettings["ClientUploadedDocuments_New"].ToString();

                if (provideddocumentsCand.StartsWith("~/"))
                {
                    provideddocumentsCand = provideddocumentsCand.Replace("~/", @"D:/wwwroot2/");
                }
                if (provideddocumentsCand.StartsWith("/"))
                {
                    provideddocumentsCand = @"D:/wwwroot2/" + provideddocumentsCand.Substring(1);
                }
                  directoryPath =  provideddocumentsCand ;
                  fileName = ImageName;
                  response = await _documentService.GetDocumentAsync(fileName, directoryPath);
                if (response.IsSuccessStatusCode)
                {
                    var jsonString = await response.Content.ReadAsStringAsync();
                    var obj = JsonConvert.DeserializeObject<DocumentResponse>(jsonString);

                    string docName = obj.DocumentName;
                    string base64Data = obj.DocumentValue;


                    fileBytes = Convert.FromBase64String(base64Data);
                    contentType = System.Web.MimeMapping.GetMimeMapping(docName);
                }
            }
            if (fileBytes == null)
            {
                if (provideddocuments.StartsWith("~/"))
                {
                    provideddocuments = provideddocuments.Replace("~/", @"D:/wwwroot2/");
                }
                if (provideddocuments.StartsWith("/"))
                {
                    provideddocuments = @"D:/wwwroot2/" + provideddocuments.Substring(1);
                }
                  directoryPath =  provideddocuments;
                  fileName = ImageName;
                  response = await _documentService.GetDocumentAsync(fileName, directoryPath);
                if (response.IsSuccessStatusCode)
                {
                    var jsonString = await response.Content.ReadAsStringAsync();
                    var obj = JsonConvert.DeserializeObject<DocumentResponse>(jsonString);

                    string docName = obj.DocumentName;
                    string base64Data = obj.DocumentValue;


                    fileBytes = Convert.FromBase64String(base64Data);
                    contentType = System.Web.MimeMapping.GetMimeMapping(docName);
                }
            }
            if (fileBytes != null)
            {
                string extension = Path.GetExtension(ImageName);
                string fileName1 = "";
                if (!string.IsNullOrWhiteSpace(extension))
                {
                    fileName1 = ImageName;
                }
                else
                {
                    fileName1 = ImageName + ".pdf";
                }
                contentType = System.Web.MimeMapping.GetMimeMapping(fileName1);
                return File(fileBytes, contentType, fileName1);
            }
            else
            {
                return RedirectToAction("Index", new { CaseStatus = "WIP" });
            }

        }

