        public void MISATG(int ClientRowId = 0)
        {
            short teamMemerRowId = Convert.ToInt16(Session["TeamMemberRowID"]);
            try
            {
                ClientCustomize cc = new ClientCustomize();
                DataSet ds = new DataSet();

                ds = cc.MISATG(ClientRowId);
                if (ds.Tables.Count > 0)
                {
                    var dt = new DataTable("Details");
                    dt = ds.Tables[0];
                    using (ClosedXML.Excel.XLWorkbook wb = new ClosedXML.Excel.XLWorkbook())
                    {
                        var ws = wb.Worksheets.Add(dt);
                        ws.Tables.FirstOrDefault().ShowAutoFilter = false;
                        //wb.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                        wb.Style.Font.Bold = true;
                        Response.Clear();
                        Response.Buffer = true;
                        Response.Charset = "";
                        Response.ContentType = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";
                        Response.AddHeader("content-disposition", "attachment;filename=MIS.xlsx");

                        using (MemoryStream MyMemoryStream = new MemoryStream())
                        {
                            wb.SaveAs(MyMemoryStream);
                            MyMemoryStream.WriteTo(Response.OutputStream);
                            Response.Flush();
                            Response.End();
                        }
                    }
                }



            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = "Invalid paramerter value";
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }
        }

        public void CandidateBulkExcel(int ClientRowId = 679)
        {
            DataSet ds1 = new DataSet();
            //ds1 = bl.getuserdata();
            //ds1 = bl.getdataBothportal();
            ClientCustomize cc = new ClientCustomize();
            int Clientrowid = 679;
            ds1 = cc.MultipalExcelDownlode(Clientrowid);
            //Set Name of DataTables.
            ds1.Tables[0].TableName = "LOA-Details";
            ds1.Tables[1].TableName = "Candidate-Details";
            ds1.Tables[2].TableName = "Education-Details";
            ds1.Tables[3].TableName = "Employment-Details";
            ds1.Tables[4].TableName = "Addrers-Details";
            ds1.Tables[5].TableName = "Criminal-Details";
            ds1.Tables[6].TableName = "Reference-Details";
            ds1.Tables[7].TableName = "National-Details";
            ds1.Tables[8].TableName = "SpecialCheck-Details";
            using (XLWorkbook wb = new XLWorkbook())
            {
                foreach (DataTable dt in ds1.Tables)
                {
                    //Add DataTable as Worksheet.
                    wb.Worksheets.Add(dt);
                }

                //Export the Excel file.
                Response.Clear();
                Response.Buffer = true;
                Response.Charset = "";
                Response.ContentType = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";
                Response.AddHeader("content-disposition", "attachment;filename=CandidateExcelExport.xlsx");
                using (MemoryStream MyMemoryStream = new MemoryStream())
                {
                    wb.SaveAs(MyMemoryStream);
                    MyMemoryStream.WriteTo(Response.OutputStream);
                    Response.Flush();
                    Response.End();
                }
            }

        }

