        [HttpPost]
        [ValidateAntiForgeryToken]
        [ValidateInput(false)]
        public ActionResult StopChecksCaseVerification(FormCollection Frm, string action)
        {
            CheckVerificationViewModel model = new CheckVerificationViewModel();
            try
            {
                string CompanyRefNo = Frm["CompanyRefNo"].ToString();
                int userId = Convert.ToInt32(Session["ClientUserRowID"].ToString());
                if (action == "Search")
                {
                    model = repoVerificationInfo.GetCheckVerificationDeatils(CompanyRefNo);
                }
                else
                {
                    if (CompanyRefNo == "")
                    {
                        ViewBag.ErrorMsg = "Please fill CompanyRefNo";
                    }
                    else
                    {
                        ClientCustomize CC = new ClientCustomize();
                        CC.UpdateCaseStopStatus(CompanyRefNo, userId);
                        ViewBag.ErrorMsg = "Case Stop Successfully !.";
                    }

                }

            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = "Invalid paramerter value";
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
                throw;
            }
            return View(model);
        }

        [HttpGet]
        [ValidateInput(false)]
        public JsonResult UpdateCheckVerification(int Id)
        {
            bool result = false;
            try
            {
                if (Id > 0)
                {
                    ClientCustomize CC = new ClientCustomize();
                    int userId = Convert.ToInt32(Session["ClientUserRowID"].ToString());
                    CC.UpdateCheckStopStatus(Id, userId);
                    result = true;
                }
                else
                {
                    ViewBag.ErrorMsg = "Invalid Id!";
                    result = false;
                }
            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = "Invalid paramerter value";
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }

            return Json(new { result }, JsonRequestBehavior.AllowGet);

        }



