        [HttpPost]
        [ValidateAntiForgeryToken]
        public ActionResult GetColorCodeReviewClientCheck(FormCollection frm)
        {
            DashboardClientCandidateListViewModel model = new DashboardClientCandidateListViewModel();
            try
            {
                int page = 1;
                string sort = "";
                string sortDir = "desc";
