        [HttpPost]
        [ValidateAntiForgeryToken]
        [ValidateInput(false)]
        public ActionResult AddCandidateCheck(FormCollection formCollection, string Search = "", string Action = "")
        {
            ClientServiceListViewModel model = new ClientServiceListViewModel();
            try
            {
                string Msg = "";
                int ClientRowID = 0;
                string DatabaseName = "New";
                int ID = Convert.ToInt32(Session["ClientRowID"]);
                Search = formCollection["SearchValue"];
                var sendInvite = Convert.ToBoolean(formCollection["sendInvite"]);
                string CandidateType = Convert.ToString(formCollection["CandidateType"]);
                ViewBag.ClientId = ID;

                DataTable dt = new DataTable();
                ClientCustomize cc = new ClientCustomize();
                ViewBag.CompanyRefNo = Search;
                if (Action != "" && Action == "Submit")
                {
                    var OldDetails = cc.GetOldPqpersonals(Search);
                    var TempDT = cc.GetExistsTempPqpersonalsDetails(Search);
                    if (OldDetails.Rows.Count == 0)
                    {
                        if (TempDT.Rows.Count > 0)
                        {
                            string[] strSubCheckRowID = formCollection["SubCheckRowID"].Split(',');
                            foreach (var item in strSubCheckRowID)
                            {
                                var SubCheckDT = cc.GetCheckdetailsWithCompanyRefNo(Convert.ToInt32(TempDT.Rows[0]["PersonalRowID"]), Convert.ToInt16(item));
                                if (SubCheckDT.Rows.Count > 0)
                                {
                                    Msg += "Check Already Exists " + SubCheckDT.Rows[0]["SubCheckName"].ToString();
                                }
                                else
                                {
                                    int rst = cc.InsertPqCandidateAddCheck(Convert.ToInt32(TempDT.Rows[0]["PersonalRowID"]), Convert.ToInt16(item), Convert.ToInt32(TempDT.Rows[0]["ClientRowID"]), CandidateType);
                                    if (rst == 1)
                                    {
                                        ViewBag.ErrorMsg = "Success";
                                    }
                                }
                            }

                            if (ViewBag.ErrorMsg == "Success" && sendInvite == true)
                            {
                                string MailSubject = "";
                                string body = "";
                                clsSendMail mail = new clsSendMail();
                                var signature = mail.GetCompanyMailSignature();
                                DataTable templateDB = new DataTable();
                                var cSmtp = repoPQClient.GetPQClientSendMailFromById(Convert.ToInt16(ID));
                                DataTable tblfractal = cc.CheckCandidateExperiencedByCandidateType(679, Convert.ToInt32(TempDT.Rows[0]["PersonalRowID"]));
                                if (tblfractal.Rows.Count > 0)
                                {
                                    if (tblfractal.Rows[0][0].ToString() == "Existing Employee")
                                    {
                                        templateDB = cc.getAlertMailtemplate(ID, "Login Details", 0, 1, "FractalExitingEmployeeAddCheck");
                                    }
                                    else
                                    {
                                        templateDB = cc.getAlertMailtemplate(ID, "Login Details", 0, 1, "FractelNewJoinerAddCheck");
                                    }
                                }
                                if (templateDB.Rows.Count > 0)
                                {
                                    body = Convert.ToString(templateDB.Rows[0]["MailTemplate"]);
                                    MailSubject = Convert.ToString(templateDB.Rows[0]["MailSubject"]);
                                }
                                DataTable d = new DataTable();
                                d = cc.CandidateEmailDocFormat_Addcheck(Convert.ToInt32(TempDT.Rows[0]["PersonalRowID"])); // it should be subcheck family based on special check, 
                                StringBuilder docString = new StringBuilder();

                                foreach (DataRow dr in d.Rows)
                                {
                                    if (dr["CheckFamilyRowID"].ToString() == "12") //address                            
                                        docString.Append("<tr><td>Employment </td><td>Experience Letter / Relieving Letter / Salary Slip / Offer Letter </td></tr>");

                                    if (dr["CheckFamilyRowID"].ToString() == "11") //address                            
                                        docString.Append("<tr><td>Education </td><td>Degree Certificate / Final Year Mark sheet </td></tr>");

                                    if (dr["CheckFamilyRowID"].ToString() == "2") //address                            
                                        docString.Append("<tr><td>Address </td><td>Address Proof for Current & Permanent Address </td></tr>");

                                    if (dr["CheckFamilyRowID"].ToString() == "26") //National Identity                            
                                        docString.Append("<tr><td>National ID Check </td><td>ID Proof </td></tr>");

                                }
                                var ClientUserRowID = Convert.ToInt32(Session["ClientUserRowID"]);
                                var dtEmail = cc.GetEmailStructureForAlert(ID, ClientUserRowID, "Case Registration");
                                var spocEmail = "";
                                var cSpocEmail = "";
                                var mobileno = "";
                                if (dtEmail.Rows.Count > 0)
                                {
                                    spocEmail = dtEmail.Rows[0]["SpocEmailID"].ToString();
                                    cSpocEmail = dtEmail.Rows[0]["CSpocEmailID"].ToString();
                                    mobileno = dtEmail.Rows[0]["mobileno"].ToString();
                                }
                                string ShowSpocId = spocEmail.ToLower();

                                ShowSpocId = ShowSpocId.Replace(",", ";");
                                string[] ShowSpocId1 = spocEmail.Split(';');
                                var MailSignature = string.Empty;
                                MailSignature = string.Concat(ShowSpocId1[0]);

                                if (signature != null)
                                {
                                    MailSignature = string.Concat("For Securitas India. <br /><br />");
                                    MailSignature = string.Concat(MailSignature, "<b>", signature.CompanyName.Trim(), "</b><br />" + mobileno,
                                    "</b><br /><b>E-mail id </b>: <a style='color:#df012a;' href='mailto:", ShowSpocId1[0], "'>", ShowSpocId1[0], "</a>");
                                }

                                var personalData = repoPQPersonal.GetTempPQPersonalDetailsForSendMailById(Convert.ToInt32(TempDT.Rows[0]["PersonalRowID"]));
                                var loginDetail = repoCandidate.GetCandidateLoginDetailsForMailSendById(Convert.ToInt32(TempDT.Rows[0]["PersonalRowID"]));

                                string ClientNameMail = Session["ClientNameMail"].ToString();
                                body = body.Replace("{Remarks}", "Please login and fill the details within 2 days");
                                body = body.Replace("{document}", docString.ToString());
                                body = body.Replace("{CandidateName}", loginDetail.CandidateName);
                                body = body.Replace("#CompanyName", ClientNameMail);
                                body = body.Replace("{ClientRefId}", personalData.ClientRefID);
                                body = body.Replace("{ExpireDate}", DateTime.Now.AddDays(7).ToString());
                                body = body.Replace("{UName}", loginDetail.UserID);
                                body = body.Replace("{UPasswd}", clsCommonMethods.PasswordDecrypt(loginDetail.UPass.Trim()));
                                body = body.Replace("{CandidateLoginUrl}", "https://bgv.securitas-india.com/Account/CLogin");

                                body = body.Replace("{MailSignature}", MailSignature);
                                string Subject = "";
                                Subject = loginDetail.CandidateName + "  Background Verification";
                                string ToMail = loginDetail.CandidateEmail;
                                string Ccmail = cSpocEmail;
                                var From = signature.GeneralEmail;
                                string[] arToMail = ToMail.Split(';');
                                ToMail = "";
                                foreach (string a in arToMail)
                                {
                                    if (!ToMail.Contains(a))
                                    {
                                        ToMail = ToMail + a.Trim() + ",";
                                    }
                                }
                                if (ToMail.Length > 1)
                                    ToMail = ToMail.Substring(0, ToMail.Length - 1);

                                Ccmail = Ccmail.Replace(",", ";");
                                arToMail = Ccmail.Split(';');
                                Ccmail = "";
                                foreach (string a in arToMail)
                                {
                                    if (!Ccmail.Contains(a))
                                    {
                                        Ccmail = Ccmail + a.Trim() + ",";
                                    }
                                }
                                if (Ccmail.Length > 1)
                                    Ccmail = Ccmail.Substring(0, Ccmail.Length - 1);
                                var DisplayName = cSmtp.ClientName.Trim();
                                var flag = mail.SendMail(DisplayName, From, ToMail, Ccmail, Subject, body);

                                ViewBag.Success = "Record Updated Successfully";
                            }

                        }
                        else
                        {
                            ViewBag.ErrorMsg = "" + Search;
                        }
                    }
                    else
                    {
                        ViewBag.ErrorMsg = "Old Case (" + Search + ") can not Process";
                    }

                    ViewBag.CompanyRefNo = "";
                }

                dt = cc.GetCandidateChecks_AddCheck(Search);
                List<ClientDashboardCheckSummaryDetailViewModel> lmd = new List<ClientDashboardCheckSummaryDetailViewModel>();
                if (dt.Rows.Count > 0)
                {
                    foreach (DataRow dr in dt.Rows) // loop for adding add from dataset to list<modeldata>
                    {
                        lmd.Add(new ClientDashboardCheckSummaryDetailViewModel
                        {
                            SecuritasID = (dr["CompanyRefNo"].ToString()),
                            CheckName = (dr["SubCheckName"].ToString()),
                            CheckStatus = dr["CheckStatus"].ToString(),
                            CheckStatusID = (dr["CheckStatusID"].ToString()),
                            OrderDate = (dr["orderDate"].ToString()),
                            OutDate = (dr["outDate"].ToString()),
                            CreatedDate = (dr["CreationDate"].ToString()),
                            ColorName = dr["ColorName"].ToString(),
                            ClientCheckRowID = Convert.ToInt32(dr["ClientCheckRowID"]),
                            Name = (dr["CandidateFullName"].ToString()),

                        });
                        DatabaseName = dr["DatabaseName"].ToString();
                    }
                    ClientRowID = Convert.ToInt32(dt.Rows[0]["ClientRowID"]);
                    model.TotalRecords = dt.Rows.Count;
                    BindSubcheckname(Convert.ToInt32(dt.Rows[0]["ClientRowID"]), Convert.ToInt32(dt.Rows[0]["PersonalRowID"]), DatabaseName);

                }
                else
                {
                    model.TotalRecords = 0;
                }
                model.PageSize = 100;
                model.ClientServiceChecks = lmd;

                GetSubChecksClientId();
                CandidateTypeDropDown();
            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = "Invalid paramerter value";
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
                return RedirectToAction("AddCandidateCheck", new { errorMsg = Ex.Message });

            }
            return View(model);
        }



        public void RblMis(int ClientRowId = 0)
        {
            short teamMemerRowId = Convert.ToInt16(Session["TeamMemberRowID"]);
            int ClientRowID = Convert.ToInt32(Session["ClientRowID"]);
            try
            {
                ClientCustomize cc = new ClientCustomize();
                DataSet ds = new DataSet();
                // ClientRowId = 860;

                ds = cc.RBLMIS(ClientRowID);
                if (ds.Tables.Count > 0)
                {
                    var dt = new DataTable("Details");
                    dt = ds.Tables[0];
                    using (ClosedXML.Excel.XLWorkbook wb = new ClosedXML.Excel.XLWorkbook())
                    {
                        var ws = wb.Worksheets.Add(dt);
                        ws.Tables.FirstOrDefault().ShowAutoFilter = false;
                        //wb.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                        wb.Style.Font.Bold = true;
                        Response.Clear();
                        Response.Buffer = true;
                        Response.Charset = "";
                        Response.ContentType = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";
                        Response.AddHeader("content-disposition", "attachment;filename=RBLMIS.xlsx");

                        using (MemoryStream MyMemoryStream = new MemoryStream())
                        {
                            wb.SaveAs(MyMemoryStream);
                            MyMemoryStream.WriteTo(Response.OutputStream);
                            Response.Flush();
                            Response.End();
                        }
                    }
                }



            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = "Invalid paramerter value";
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }
        }

