        [ValidateInput(false)]
        public async Task<ActionResult> ClientZip(string PersonalRowIDs = "")
        {
            PersonalRowIDs = clsCommonMethods.PDecrypt(PersonalRowIDs);
            ClientCustomize cc = new ClientCustomize();
            DataTable dtable = new DataTable();
            dtable = cc.CandidateZip(PersonalRowIDs);
            List<string> pdfFilePaths = new List<string>();
            if (dtable.Rows.Count > 0)
            {
                foreach (DataRow dr in dtable.Rows)
                {


                    if ((dr["CandidateOtherPath"].ToString() == "" || dr["CandidateOtherPath"].ToString() == null) && (dr["LOA_PhotoPath"].ToString() == "" || dr["LOA_PhotoPath"].ToString() == null))
                    {
                        string FldPathDoc = dr["filepath"].ToString();
                        if (FldPathDoc.StartsWith("~/"))
                        {
                            FldPathDoc = FldPathDoc.Replace("~/", @"D:/wwwroot2/");
                        }
                        if (FldPathDoc.StartsWith("/"))
                        {
                            FldPathDoc = @"D:/wwwroot2/" + FldPathDoc.Substring(1);
                        }
                        //   var fname = Server.MapPath(dr["filepath"].ToString()) + dr["filename"].ToString();
                        var fname = FldPathDoc + dr["filename"].ToString();
                        pdfFilePaths.Add(fname);
                    }
                    else if ((dr["CandidateOtherPath"].ToString() == "" || dr["CandidateOtherPath"].ToString() == null))
                    {
                        string FldPathDoc = dr["filepath"].ToString();
                        if (FldPathDoc.StartsWith("~/"))
                        {
                            FldPathDoc = FldPathDoc.Replace("~/", @"D:/wwwroot2/");
                        }
                        if (FldPathDoc.StartsWith("/"))
                        {
                            FldPathDoc = @"D:/wwwroot2/" + FldPathDoc.Substring(1);
                        }

                        //var fname = Server.MapPath(dr["filepath"].ToString()) + dr["filename"].ToString();
                        var fname = FldPathDoc + dr["filename"].ToString();
                        var fnameimg = dr["LOA_PhotoPath"].ToString();
                        pdfFilePaths.Add(fname);
                        pdfFilePaths.Add(fnameimg);
                    }
                    else if ((dr["LOA_PhotoPath"].ToString() == "" || dr["LOA_PhotoPath"].ToString() == null))
                    {
                        string FldPathDoc = dr["filepath"].ToString();
                        if (FldPathDoc.StartsWith("~/"))
                        {
                            FldPathDoc = FldPathDoc.Replace("~/", @"D:/wwwroot2/");
                        }
                        if (FldPathDoc.StartsWith("/"))
                        {
                            FldPathDoc = @"D:/wwwroot2/" + FldPathDoc.Substring(1);
                        }
                        var fname = FldPathDoc + dr["filename"].ToString();
                        //var fname = Server.MapPath(dr["filepath"].ToString()) + dr["filename"].ToString();
                        var fnameexcel = dr["CandidateOtherPath"].ToString();
                        pdfFilePaths.Add(fname);
                        pdfFilePaths.Add(fnameexcel);
                    }

                    else
                    {
                        string FldPathDoc = dr["filepath"].ToString();
                        if (FldPathDoc.StartsWith("~/"))
                        {
                            FldPathDoc = FldPathDoc.Replace("~/", @"D:/wwwroot2/");
                        }
                        if (FldPathDoc.StartsWith("/"))
                        {
                            FldPathDoc = @"D:/wwwroot2/" + FldPathDoc.Substring(1);
                        }

                        var fname = FldPathDoc + dr["filename"].ToString();
                        //var fname = Server.MapPath(dr["filepath"].ToString()) + dr["filename"].ToString();
                        var fnameimg = dr["LOA_PhotoPath"].ToString();
                        var fnameexcel = dr["CandidateOtherPath"].ToString();

                        pdfFilePaths.Add(fname);
                        pdfFilePaths.Add(fnameimg);
                        pdfFilePaths.Add(fnameexcel);
                    }
                    //var fname = Server.MapPath(dr["filepath"].ToString()) + dr["filename"].ToString();
                    //var fnameimg = dr["LOA_PhotoPath"].ToString();
                    //var fnameexcel = dr["CandidateOtherPath"].ToString();

                    //pdfFilePaths.Add(fname);
                    //pdfFilePaths.Add(fnameimg);
                    //pdfFilePaths.Add(fnameexcel);
                }
            }

            if (pdfFilePaths.Count == 0 || pdfFilePaths == null)
            {
                return HttpNotFound();
            }
            using (MemoryStream zipMemoryStream = new MemoryStream())
            {
                using (ZipArchive zipArchive = new ZipArchive(zipMemoryStream, ZipArchiveMode.Create, true))
                {
                    bool anyDocumentAdded = false;
                    foreach (string pdfFilePath in pdfFilePaths)
                    {
                        HttpResponseMessage response = await _documentService.GetDocumentAsync(Path.GetFileName(pdfFilePath), Path.GetDirectoryName(pdfFilePath) + Path.DirectorySeparatorChar);
                        if (response.IsSuccessStatusCode)
                        {
                            var jsonString = await response.Content.ReadAsStringAsync();
                            var obj = JsonConvert.DeserializeObject<DocumentResponse>(jsonString);
                            if (obj != null && !string.IsNullOrEmpty(obj.DocumentValue))
                            {
                                string docName = obj.DocumentName;
                                string base64Data = obj.DocumentValue;

                                byte[] fileBytes = Convert.FromBase64String(base64Data);
                                ZipArchiveEntry entry = zipArchive.CreateEntry(docName);

                                using (Stream entryStream = entry.Open())
                                {
                                    entryStream.Write(fileBytes, 0, fileBytes.Length);
                                }

                                anyDocumentAdded = true;
                                continue;

                            }


                        }

                        //if (System.IO.File.Exists(pdfFilePath))
                        //{
                        //    ZipArchiveEntry pdfEntry = zipArchive.CreateEntry(Path.GetFileName(pdfFilePath));

                        //    using (Stream entryStream = pdfEntry.Open())
                        //    {
                        //        using (FileStream fileStream = new FileStream(pdfFilePath, FileMode.Open))
                        //        {
                        //            fileStream.CopyTo(entryStream);
                        //        }
                        //    }
                        //}

                    }
                    if (!anyDocumentAdded)
                    {
                        return HttpNotFound();
                    }

                }
                zipMemoryStream.Seek(0, SeekOrigin.Begin);
                return File(zipMemoryStream.ToArray(), "application/zip", "Candidate_Document.zip");
            }
        }



        [ValidateInput(false)]
        public async Task<ActionResult> DownloadLOA(string PersonalRowIDs = "")
        {
            byte[] fileBytes = null;
            string contentType = "";
            string directoryPath = @"D:/wwwroot2/Documents/CandidateDocuments/provideddocuments/";
            string fileName = "Letter_Of_Authorization" + Convert.ToString(clsCommonMethods.PDecrypt(PersonalRowIDs)) + ".pdf";
            HttpResponseMessage response = await _documentService.GetDocumentAsync(fileName, directoryPath);


            if (response.IsSuccessStatusCode)
            {
                var jsonString = await response.Content.ReadAsStringAsync();
                var obj = JsonConvert.DeserializeObject<DocumentResponse>(jsonString);

                string docName = obj.DocumentName;
                string base64Data = obj.DocumentValue;


                 fileBytes = Convert.FromBase64String(base64Data);
                contentType = System.Web.MimeMapping.GetMimeMapping(docName);
                if (fileBytes != null)
                {
                    return File(fileBytes, contentType, fileName);
                }
            }
            return File(fileBytes, contentType, fileName);
        }

        public int GetDetailsfromPDF_OCR(HttpPostedFileBase File, int Pid, int Cid, string bgcF)
        {
            int status = 0;
            try
            {
                TextInfo textInfo = new CultureInfo("en-US", false).TextInfo;
                CandidateOCRDetails candidateOCRDetails = new CandidateOCRDetails();
                PDFOCR pDFOCR = new PDFOCR();
                ClientCustomize cc = new ClientCustomize();
                DataTable dt = new DataTable();
                candidateOCRDetails = pDFOCR.GetPdfContainsfromPDF(File, bgcF);

                var DTCheckList = cc.GetPQCandidateCheckList(Pid);
                string CandidateName = "";
                string FatherName = "";
                if (candidateOCRDetails.personalDetails.Name != null)
                {
                    if (Cid!=3)
                    {
                        if (bgcF == "TCS APPLICATION FORM AND BGC FORM")
                        {
                            CandidateName = candidateOCRDetails.personalDetails.Name.Split('.')[1].ToString().Trim();
                            if (candidateOCRDetails.personalDetails.FathersName != null)
                            {
                                FatherName = candidateOCRDetails.personalDetails.FathersName.Split('.')[1].ToString().Trim();
                            }
                        }
                        else
                        {
                            CandidateName = candidateOCRDetails.personalDetails.Name;
                        }

                        dt = cc.Antecedents_client_select_form(Cid, 0, "Data Entry", "Case");
                        if (dt.Rows.Count > 0)
                        {
                            status = 1;
                            for (int i = 0; i < dt.Rows.Count; i++)
                            {
                                CandidateDEModel cd = new CandidateDEModel();
                                cd.PersonalRowID = Pid;
                                cd.clientRowId = Cid;
                                cd.CreatedBy = Convert.ToInt32(Session["TeamMemberRowID"]);
                                cd.moduleName = "DETM";
                                cd.AntecedentRowID = Convert.ToInt64(dt.Rows[i]["AntecedentsRowID"]);
                                string[] FString = Convert.ToString(dt.Rows[i]["QLabel"]).Split('_');
                                cd.DisplayName = FString[1];
                                if (Convert.ToString(dt.Rows[i]["AntecedentsRowID"]) == "24")//Title
                                {
                                    string Title = "Mr.";
                                    if (candidateOCRDetails.personalDetails.Gender != null)
                                    {
                                        if (Convert.ToString(candidateOCRDetails.personalDetails.Gender).ToUpper() == "FEMALE")
                                        {
                                            Title = "Ms.";
                                        }
                                        cd.DataEntryValue = Title;
                                        var result = cc.tblDataEntry_Insert(cd);
                                    }

                                }
                                else if (Convert.ToString(dt.Rows[i]["AntecedentsRowID"]) == "121")// Candidate Name
                                {
                                    if (candidateOCRDetails.personalDetails.Name != null)
                                    {
                                        cd.DataEntryValue = Convert.ToString(CandidateName);
                                        var result = cc.tblDataEntry_Insert(cd);
                                    }
                                }
                                else if (Convert.ToString(dt.Rows[i]["AntecedentsRowID"]) == "122")//Father's Name 
                                {
                                    if (FatherName != "")
                                    {
                                        cd.DataEntryValue = Convert.ToString(FatherName);
                                        var result = cc.tblDataEntry_Insert(cd);
                                    }

                                }
                                else if (Convert.ToString(dt.Rows[i]["AntecedentsRowID"]) == "5")//Date Of Birth
                                {
                                    if (candidateOCRDetails.personalDetails.DateofBirth != null)
                                    {
                                        cd.DataEntryValue = Convert.ToDateTime(candidateOCRDetails.personalDetails.DateofBirth).ToString("dd-MM-yyyy");
                                        var result = cc.tblDataEntry_Insert(cd);
                                    }

                                }
                                else if (Convert.ToString(dt.Rows[i]["AntecedentsRowID"]) == "13")//Gender
                                {
                                    if (candidateOCRDetails.personalDetails.Gender != null)
                                    {
                                        cd.DataEntryValue = Convert.ToString(candidateOCRDetails.personalDetails.Gender);
                                        var result = cc.tblDataEntry_Insert(cd);
                                    }

                                }
                                else if (Convert.ToString(dt.Rows[i]["AntecedentsRowID"]) == "19")//Mobile No
                                {
                                    if (candidateOCRDetails.PresentAddress.Telephone != null)
                                    {
                                        cd.DataEntryValue = Convert.ToString(candidateOCRDetails.PresentAddress.Telephone);
                                        var result = cc.tblDataEntry_Insert(cd);
                                    }

                                }
                                else if (Convert.ToString(dt.Rows[i]["AntecedentsRowID"]) == "8")//Email ID
                                {
                                    if (candidateOCRDetails.personalDetails.Email != null)
                                    {
                                        cd.DataEntryValue = Convert.ToString(candidateOCRDetails.personalDetails.Email);
                                        var result = cc.tblDataEntry_Insert(cd);
                                    }

                                }
                                else if (Convert.ToString(dt.Rows[i]["AntecedentsRowID"]) == "124")//ID Number
                                {
                                    if (candidateOCRDetails.personalDetails.PANCardNo != null)
                                    {
                                        cd.DataEntryValue = Convert.ToString(candidateOCRDetails.personalDetails.PANCardNo);
                                        var result = cc.tblDataEntry_Insert(cd);
                                    }

                                }
                                else if (Convert.ToString(dt.Rows[i]["AntecedentsRowID"]) == "4")//Client Ref ID
