                                        }
                                        else
                                        {
                                            cd.DataEntryValue = "Experienced";
                                        }
                                        var result = cc.tblDataEntry_Insert(cd);
                                    }

                                }
                            }
                        }

                        //Address
                        DataRow[] ADDrowsFiltered = DTCheckList.Select("CheckFamilyRowID=2");
                        if (ADDrowsFiltered.Length > 0)
                        {
                            status = 1;
                            int count = ADDrowsFiltered.Length;
