        public string ProcessWorldCheckReport(string CompanyRefNo, int Cid, int PersonalRowid, int SubCheckid, string DOB, string Gender, string Country, string CandidateName)
        {
            string Result = "";
            try
            {
                DataTable dt = new DataTable();
                string CaseId = "";
                var Time_stamp = new DateTimeOffset(Convert.ToDateTime(DateTime.Now)).ToUnixTimeSeconds();

                //string Country = "Overseas";
                if (Gender is null)
                {
                    Gender = "";
                }
                if (Gender != "")
                {
                    // int SubCheckid = 888;
                    string Location = "";
                    var DOB_ = Convert.ToDateTime(DOB).ToString("dd-MM-yyyy").Split('-');
                    string Month = getMonth(DOB_[1]);
                    string DoB = DOB_[0] + "-" + Month + "-" + DOB_[2];
                    var tblCase = cc.GetWorldCheckscreeningRequest(PersonalRowid, SubCheckid);
                    var ResultJson = "";
                    if (tblCase.Rows.Count > 0)
                    {
                        ResultJson = Convert.ToString(tblCase.Rows[0]["JsonResult"]);
                    }
                    else
                    {
                        CaseId = CompanyRefNo.Replace(" ", "").Trim() + "_" + Time_stamp.ToString();
                        ResultJson = WorldCheckscreeningRequest(CaseId, PersonalRowid, 888, CandidateName, DoB, Convert.ToString(Gender), Location);
                    }
                    if (Convert.ToString(ResultJson) != "")
                    {
                        refinitivRootobject myDeserializedClass = JsonConvert.DeserializeObject<refinitivRootobject>(ResultJson);

                        if (myDeserializedClass.results.Length > 0)
                        {
                            int cnt = 1;
                            foreach (var item in myDeserializedClass.results)
                            {
                                cc.InsertWorldCheckResultIds(PersonalRowid, SubCheckid, item.resultId, item.referenceId, cnt);
                                cnt = cnt + 1;
                            }
                        }
                        if (myDeserializedClass.results.Length > 0)
                        {

                            cc.UpdateCheckStatus(PersonalRowid, Convert.ToInt16(SubCheckid), 1, 115, "Check", Convert.ToInt32(Session["TeamMemberRowID"].ToString()));
                            clsCommonMethods.AddCheckActionHistory(PersonalRowid, Convert.ToInt16(SubCheckid), "Allocated-Mgr", "Report Verifeid By World Check API");
                            cc.UpdateSpecialCheckTeamMembers(PersonalRowid, SubCheckid);
                        }
                        else
                        {
                            CaseId = myDeserializedClass.caseId;
                            var reportresult = WorldChecksRequestAsyncReport(CaseId, "NoMatchFound");
                            if (reportresult != "")
                            {
                                var stastus = WorldChecksGetReportStatus(reportresult);
                                if (stastus == "COMPLETED")
                                {
                                    var reportname = WorldChecksDownloadReport(reportresult, PersonalRowid, SubCheckid, CompanyRefNo);
                                    if (reportname != "")
                                    {
                                        var rst = cc.UpdateCandidateChecksReportComments(PersonalRowid, Convert.ToInt16(SubCheckid));
                                        cc.UpdatePQCandidateChecksColorCode(905, 6, "Green", PersonalRowid, SubCheckid);
                                        cc.UpdateCheckStatus(PersonalRowid, Convert.ToInt32(SubCheckid), 1, 36, "Check", Convert.ToInt32(Session["ClientUserRowID"].ToString()));
                                        clsCommonMethods.AddCheckActionHistoryByClient(PersonalRowid, Convert.ToInt16(SubCheckid), "Allocated-Mgr", "World Check Report Verifeid By Client Window");
                                        cc.UpdateSpecialCheckTeamMembers(PersonalRowid, SubCheckid);
                                        Result = "Case created on the Vendor Portal,and Report Download, Please check the process with the RWQC Team";
                                    }
                                    else
                                    {
                                        cc.UpdateCheckStatus(PersonalRowid, Convert.ToInt32(SubCheckid), 1, 115, "Check", Convert.ToInt32(Session["ClientUserRowID"].ToString()));
                                        clsCommonMethods.AddCheckActionHistoryByClient(PersonalRowid, Convert.ToInt16(SubCheckid), "Allocated-Mgr", "World Check Report Verifeid By Client Window");
                                        cc.UpdateSpecialCheckTeamMembers(PersonalRowid, SubCheckid);
                                        Result = "Case created on the Vendor Portal, but the report did not download. Please check the process with the Operations Team";
                                    }
                                }
                                else
                                {
                                    cc.UpdateCheckStatus(PersonalRowid, Convert.ToInt32(SubCheckid), 1, 115, "Check", Convert.ToInt32(Session["ClientUserRowID"].ToString()));
                                    clsCommonMethods.AddCheckActionHistoryByClient(PersonalRowid, Convert.ToInt16(SubCheckid), "Allocated-Mgr", "World Check Report Verifeid By Client Window");
                                    cc.UpdateSpecialCheckTeamMembers(PersonalRowid, SubCheckid);
                                    Result = "Case created on the Vendor Portal, but the report did not download. Please check the process with the Operations Team";
                                }

                            }
                            else
                            {
                                cc.UpdateCheckStatus(PersonalRowid, Convert.ToInt32(SubCheckid), 1, 115, "Check", Convert.ToInt32(Session["ClientUserRowID"].ToString()));
                                clsCommonMethods.AddCheckActionHistoryByClient(PersonalRowid, Convert.ToInt16(SubCheckid), "Allocated-Mgr", "World Check Report Verifeid By Client Window");
                                cc.UpdateSpecialCheckTeamMembers(PersonalRowid, SubCheckid);
                                Result = "Case created on the Vendor Portal, but the report did not download. Please check the process with the Operations Team";
                            }
                        }
                    }
                }

            }
            catch (Exception Ex)
            {
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
                Result = "Check Process to Data Entry";
                Result = "Case not created on the Vendor Portal. Please check the process with the Data Entry";
            }
            return Result;
        }

        public string getMonth(string month)
        {
            string stringMonth = "";
            if (month == "01")
            {
                stringMonth = "Jan";
            }
            else if (month == "02")
            {
                stringMonth = "Feb";
            }
            else if (month == "03")
            {
                stringMonth = "Mar";
            }
            else if (month == "04")
            {
                stringMonth = "Apr";
            }
            else if (month == "05")
            {
                stringMonth = "May";
            }
            else if (month == "06")
            {
                stringMonth = "Jun";
            }
            else if (month == "07")
            {
                stringMonth = "Jul";
            }
            else if (month == "08")
            {
                stringMonth = "Aug";
            }
            else if (month == "09")
            {
                stringMonth = "Sep";
            }
            else if (month == "10")
            {
