        public PanRoot PanFileOcr(HttpPostedFileBase Image1)
        {
            var client = new RestClient("https://api.karza.in");
            var request = new RestRequest("https://api.karza.in/v3/ocr-plus/kyc", Method.POST);
            byte[] imagePass = new byte[Image1.ContentLength];
            Image1.InputStream.Read(imagePass, 0, imagePass.Length);
            request.AddHeader("Accept", "application/json");
            request.AddHeader("x-karza-key", "uLrWYikM3MniDQR");
            request.AddFile("file", imagePass, Image1.FileName, Image1.ContentType);
            var response = client.ExecuteAsync(request);
            var test = response.Result;
            var result1 = response.Result.Content;
            PanRoot myDeserializedClass = JsonConvert.DeserializeObject<PanRoot>(result1);

            return myDeserializedClass;
        }
