        {
            CandidatePersonalInfoViewModel Model = new CandidatePersonalInfoViewModel();
            try
            {               
                ClientCustomize CC = new ClientCustomize();
                int PersonalRowID = Convert.ToInt32(clsCommonMethods.PDecrypt(PersonalRowId));
