        [HttpPost]
        public JsonResult CheckDuplicate(string MobileNo, string EmailId)
        {
            try
            {
                DataTable dt = cc.GetDuplicate(MobileNo, EmailId);

                if (dt != null && dt.Rows.Count > 0)
                {
                    return Json(new
                    {
                        isDuplicate = true,
                        companyRefNo = dt.Rows[0]["CompanyRefNo"].ToString(),
                        name = dt.Rows[0]["CandidateName"].ToString()
                    });
                }
            }
            catch (Exception ex)
            {
                return Json(new { isDuplicate = false, error = ex.Message });
            }

            return Json(new { isDuplicate = false });
        }

        [HttpGet]
        public ActionResult Reviewdetail(string strYear = "All Years", string strMonth = "All Months" , string strclid = "")
        {
            ClientDashBoardTableModel model = new ClientDashBoardTableModel();
            try
            {

                string stYear = null;
                string stMonth = null;

                if (strYear == "All Years")
                {
                    stYear = null;
                }
                else
                {
                    stYear = strYear;
                }

                if (strMonth == "All Months")
                {
                    stMonth = null;
                }
                else
                {
                    stMonth = strMonth;
                }

                int allClients = 0;
                short ClientRowID = Convert.ToInt16(Session["ClientRowID"]);
                int ClientUserRowID = Convert.ToInt32(Session["ClientUserRowID"]);
                string CreatedBy = Convert.ToString(Session["CreatedBy"]);
                string valid = Session["Valid"].ToString();

                if (strclid != "")
                {
                    ClientRowID = Convert.ToInt16(strclid);
                }
               




                if (valid == "0")
                {
                    ViewBag.ErrorMsg = "Invalid User!";
                    Session.Abandon();
                    Response.Redirect("/Account/ApplicationError");
                }

                ViewBag.ClientDashboard = "Client Dashboard!";

                ClientDashboardViewModel dashboardData;

                if (!string.IsNullOrEmpty(CreatedBy) && CreatedBy == "Client-User")
                {
                    dashboardData = repoDashboardClient.GetClientDashBoardChartInfo1DBGraph(ClientRowID, ClientUserRowID, allClients, stYear, stMonth);
                }
                else
                {
                    dashboardData = repoDashboardClient.GetClientDashBoardChartInfo1DBGraph(ClientRowID, 0, allClients, stYear, stMonth);
                }

                ViewBag.ClientCasesDashboard = dashboardData;
                ViewBag.ClientCasesDashboardCheck = dashboardData.CheckFamilies;

                DataTable dt1 = new DataTable();
                DataTable dt2 = new DataTable();
                DataTable dt3 = new DataTable();

                List<ClientDashBoardTable> lmd1 = new List<ClientDashBoardTable>();
                List<DashBoardMonthCaseData> lmd2 = new List<DashBoardMonthCaseData>();
                List<DashBoardColorCodeCount> lmd3 = new List<DashBoardColorCodeCount>();
                dt1 = cc.ClientDashboard_AnalysisDBGraph(ClientRowID, "TOTALCASESBYSTATUSDAYWISE", stYear, stMonth);
                dt2 = cc.ClientDashboard_AnalysisDBGraph(ClientRowID, "TOTALCASEINITIATED", stYear, stMonth);
                dt3 = cc.ClientDashboard_AnalysisDBGraph(ClientRowID, "TOTALCASESBYCOLORCODE", stYear, stMonth);

                if (dt1.Rows.Count > 0)
                {
                    foreach (DataRow dr in dt1.Rows)
                    {
                        lmd1.Add(new ClientDashBoardTable
                        {
                            ClientStatus = dr["ClientStatus"].ToString(),
                            fiveDays = Convert.ToInt32(dr["1-5 Days"]),
                            tenDays = Convert.ToInt32(dr["6-10 Days"]),
                            fifteenDays = Convert.ToInt32(dr["11-15 Days"]),
                            twentyDays = Convert.ToInt32(dr["16-20 Days"]),
                            twentyplusDays = Convert.ToInt32(dr["20+ Days"]),
                            Total = Convert.ToInt32(dr["Grand Total"]),

                        });
                        model.ClientDashBoardTable = lmd1;
                    }
                }

                if (dt2.Rows.Count > 0)
                {
                    foreach (DataRow dl in dt2.Rows)
                    {
                        lmd2.Add(new DashBoardMonthCaseData
                        {
                            monthname = dl["Month"].ToString(),
                            mCount = Convert.ToInt32(dl["Count"]),

                        });
                        model.DashBoardMonthCaseData = lmd2;
                    }
                }

                if (dt3.Rows.Count > 0)
                {
                    foreach (DataRow dp in dt3.Rows)
                    {
                        lmd3.Add(new DashBoardColorCodeCount
                        {
                            CColorName = dp["Color"].ToString(),
                            CCount = Convert.ToInt32(dp["Count"]),

                        });
                        model.DashBoardColorCodeCount = lmd3;
                    }
                }


                // Pass chart data to view as JSON
                ViewBag.ChartData = JsonConvert.SerializeObject(dashboardData.ChartData);
                ViewBag.ChartData1 = JsonConvert.SerializeObject(dashboardData.CheckFamilies);
                ViewBag.clientrowid = Convert.ToInt16(Session["ClientRowID"]);
                BindClientListByLogInName(ViewBag.clientrowid, ClientUserRowID);

                //CreateNavigationforInsuffCaseForClient();
                //BindClientListByLogInName(ClientRowID, ClientUserRowID);
            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = "Invalid parameter value";
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }

            ViewBag.SelectedMonth = strMonth;
            ViewBag.SelectedYear = strYear;
            ViewBag.SelectedClient = strclid;
            return View(model);

        }

        [HttpPost]
        public JsonResult UpdateActiveStatus(int PersonalRowID, int Status)
        {
            try
            {
                using (SqlConnection con = new SqlConnection(DAS.ConnectionString))
                {
                    using (SqlCommand cmd = new SqlCommand("dbo.uspUpdateCandidateActiveStatus", con))
                    {
                        cmd.CommandType = CommandType.StoredProcedure;
                        cmd.Parameters.AddWithValue("@PersonalRowID", PersonalRowID);
                        cmd.Parameters.AddWithValue("@IsActive", Status == 1);
                        con.Open();
                        cmd.ExecuteNonQuery();
                    }
                }
                return Json(new { success = true });
            }
            catch (Exception ex)
            {
                return Json(new { success = false, message = ex.Message });
            }
        }
    }
